    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins with smaller post_residual (Best Fit).
    // Penalize large gaps that are too small for common items.
    if post_residual < 10 {
        score -= 50.0; // Reward tight packing
    } else if post_residual < 20 {
        score += 20.0; // Penalize near-empty gaps
    }

    // 2. Harmonic Lookahead: If next_item_size fits in the post_residual,
    // strongly prefer this bin to preserve future capacity.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // 3. Pressure Management: If this is the only fitting bin (fitting_bins_count == 1),
    // discourage opening a new bin by making the current bin very attractive.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // 4. New Bin Logic: If we are considering a new bin (bin_residual == bin_capacity),
    // heavily penalize it unless the existing open bins are "too full" to handle the item.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 80.0 + (mean_residual * 0.5);
        }
    }

    // 5. Harmonic Class Adjustment: Favor bins that leave a residual which is a multiple of 
    // common item sizes or leaves room for a "remainder" that matches the mean_residual.
    let residual_alignment = (post_residual as f64 - mean_residual).abs();
    score += residual_alignment * 0.2;

    // 6. Progression Scaling: As the stream nears completion, become more aggressive 
    // about closing bins (minimizing total bins used).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Strategy: 
    // 1. Prioritize Best-Fit (minimize post_residual).
    // 2. Penalize opening a new bin early unless the existing fits are highly suboptimal (large post_residual).
    // 3. Use lookahead next_item_size to discourage creating residuals that cannot fit the next item.

    let mut score = post * 1.5;

    // Penalty for creating a bin with "dead space" that cannot fit the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // If this is a new bin (bin_residual == capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we are struggling to fit items into existing ones
        // or if our current bins are mostly full (high mean_residual indicates empty space)
        let new_bin_penalty = 40.0 + (mean_residual * 0.5) + (progress * 20.0);
        score = new_bin_penalty;
    } else {
        // If fitting_bins_count is low, we are running out of options; reward utilizing existing bins
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Non-linear coupling: punish residuals that are too small to be useful for future items
        // but not small enough to be a perfect fit.
        if post_residual > 0 && post_residual < 20 {
            score += (20.0 - post_residual as f64).powf(1.5);
        }
    }

    // Global pressure: as we approach the end of the stream, prioritize packing density
    score += (1.0 - progress) * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

