    // However, we apply a non-linear scaling to avoid "sliver" waste (residuals < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Penalty for creating unusable slivers
    }

    // 2. Lookahead Logic: If next_item_size is large, avoid leaving small residuals.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize placements that block the next item from fitting
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward placements that leave exactly enough room for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Harmonic Pressure: Use modulo arithmetic to favor bin states that align with 
    // common divisors of the capacity (100).
    let harmonic_alignment = (post_residual % 25) as f64;
    score += harmonic_alignment * 0.8;

    // 4. New Bin Thresholding: If this is an empty bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the open bins are "crowded" or if we have no fit.
        // We set a base cost for opening a new bin that increases as we approach the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        let new_bin_base_cost = 35.0 + (progress * 15.0);

        if fitting_bins_count == 0 {
            score = 0.0; // Must open new bin
        } else {
            score = new_bin_base_cost;
        }
    } else {
        // 5. Global Density Awareness: Penalize using many bins if the mean residual is high.
        // This encourages filling existing bins more aggressively.
        score += (open_bins_count as f64 * 2.0) - (mean_residual * 0.2);
    }

    score
