    // We penalize residuals in the [1, 15] range, as they are rarely useful for 10-80 range items.
    if post > 0.0 && post < 16.0 {
        score += (16.0 - post).powi(2) * 5.0;
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // we heavily reward this bin to keep the bin chain tight.
