pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space that is too small for most items (under 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Aggressive Lookahead: If the post_residual is a near-perfect fit for the next item, prioritize it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize if current placement forces a new bin for the next item
            score += 25.0;
        }
    }

    // 3. Balance usage across bins: Avoid creating bins with high residuals compared to the global mean.
    // If this bin's post_residual is significantly higher than the mean, penalize it to encourage packing into tighter bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // 4. New Bin Logic: If we are forced to open a new bin, only do so if the current open bins are very "full"
    // or if we have very few fitting options.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to discourage it.
        score = 150.0;
        // Reduce the penalty if the number of open bins is low or the item is large
        score -= (open_bins_count as f64) * 2.0;
        score -= (item_size as f64) * 0.5;
    } else {
        // If it's the last chance (fitting_bins_count == 1), reward taking the spot to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic:
    // If post_residual is small, it might prevent future items from fitting.
    // If post_residual is in the range (0, 10), it is "dangerous" space.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 3. Lookahead integration:
    // If next_item_size fits in the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it leaves a "clean" remainder (e.g., multiple of 10)
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 15.0;
        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only open if existing
    // bins have poor fitting potential.
    if bin_residual == bin_capacity {
        // High base cost to open new bin, reduced if open_bins_count is low
        score += 60.0 - (open_bins_count as f64 * 2.0);
    } else {
        // Encourage using existing bins that have a residual close to the mean
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 5. Urgency:
    // If this is the last chance to fit an item (fitting_bins_count == 1),
    // prioritize this bin to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that is too small for likely future items
    // If post_residual is small but > 0, it is often a "bad" fit.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
    }

    // Harmonic Class logic: Favor bins that leave a residual which is a multiple 
    // of common item sizes, or aligns with the next_item_size to minimize fragmentation.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect fit for the next item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.2;
        } else {
            // Penalize if the current bin cannot accommodate the lookahead item
            score += 15.0;
        }
    }

    // Heuristic for opening new bins:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the
    // current open bins are "bad" (i.e., they would leave very small residuals).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 15.0 {
            // New bin is better than forced bad fits in existing bins
            score -= 20.0;
        } else {
            // Otherwise, strongly penalize opening a new bin
            score += 60.0;
        }
    }

    // Favor bins that are already partially filled (Best Fit variant)
    // Avoid creating too many open bins (load balancing)
    score += (open_bins_count as f64) * 2.0;

    // Progress-based scaling: towards the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic.
    // The objective is to minimize post_residual (Best Fit), but penalize "fragmentation" 
    // where the remaining space is too small for common item sizes, 
    // while biasing towards keeping bins balanced relative to the mean_residual.

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: If post_residual is small (1-9), it is almost always unusable.
    // We penalize these "dead zones" heavily unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2. Lookahead Synergy: If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Strong reward for accommodating the next item
        } else {
            score += 10.0; // Penalize if we block the next item from fitting here
        }
    }

    // 3. Harmonic Balance: Prevent extreme variance in bin utilization.
    // If this bin's residual is significantly lower than the mean_residual, 
    // we are packing too tightly compared to others; bias against it to spread load.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. Threshold Logic: If this is the last fitting bin, we are forced to use it.
    // We make it slightly more attractive to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. New Bin Constraint: Only open a new bin if the best existing fit is truly terrible (post_residual > 30).
    if bin_residual == bin_capacity {
        if post_residual > 30 {
            score = 25.0; // Base cost to open a new bin
        } else {
            score = 100.0; // Penalize opening new bin if current fit is decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (fragments smaller than the smallest possible item)
    // We treat 10 as the lower bound of item sizes for heuristic weighting.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if we can fit the next item perfectly or nearly perfectly, 
    // favor bins that leave exactly that much space.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // If the current bin will be the only one that can fit the next item, 
        // heavily penalize it if it becomes too full to accept that next item.
        if post_residual < next_item_size {
            score += 40.0;
        }
    }

    // Favor bins that are closer to the global mean residual to keep distribution uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // If this is the last chance for the current item, reduce penalty to force placement
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Logic for new bin (bin_residual == bin_capacity):
    // Only open a new bin if the best available fit is extremely poor (post_residual < 10)
    // or if the current bin occupancy is inefficient.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High threshold to prevent opening new bins unnecessarily
            score = 35.0; 
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best-Fit (smaller post_residual is better)
    let mut score = post;

    // Penalty for creating "dead zones": if the residual is too small to fit common items 
    // but large enough to waste space, penalize it quadratically.
    // We treat 1-9 as unusable dead space.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 5.0;
    }

    // Lookahead coupling: If the next item is large, penalize small residuals 
    // that won't accommodate it, unless the current fit is perfect (0).
    if next_item_size > 0 {
        if post > 0.0 && post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 2.0;
        }
    }

    // Stream progression adjustment: As the stream nears completion, 
    // become more aggressive about filling existing bins to avoid leaving 
    // too many bins with high residuals.
    if progress > 0.8 {
        score -= (mean_residual - post) * (progress * 2.0);
    }

    // New bin threshold logic: 
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // We only want to open a new bin if the best available fit is "bad" (e.g., leaves < 15 space).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have existing bins that could take the item
            score += 40.0 + (mean_residual * 0.5);
        } else {
            // Must open new bin
            score = 0.0;
        }
    }

