        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0 * (1.0 - progress);
        }

        // 4. Fragment Penalty: Avoid creating bins with small, unusable residuals (e.g., 1-9).
        // If the resulting residual is small, it's effectively dead space.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // 5. Global State Coupling: If this bin's residual is much higher than the mean, 
        // it is a "loose" bin. We want to fill it rather than open a new one.
        if (bin_residual as f64) > mean_residual {
            score -= 10.0;
        }

        // 6. Last Chance Logic: If this is the only bin that can fit the item, 
        // prioritize it strongly to avoid unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
