        if post_residual >= next_item_size {
            score -= 15.0; // Strong reward for accommodating the next item
        } else {
            score += 10.0; // Penalize if we block the next item from fitting here
        }
    }

    // 3. Harmonic Balance: Prevent extreme variance in bin utilization.
    // If this bin's residual is significantly lower than the mean_residual, 
    // we are packing too tightly compared to others; bias against it to spread load.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. Threshold Logic: If this is the last fitting bin, we are forced to use it.
    // We make it slightly more attractive to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. New Bin Constraint: Only open a new bin if the best existing fit is truly terrible (post_residual > 30).
    if bin_residual == bin_capacity {
        if post_residual > 30 {
            score = 25.0; // Base cost to open a new bin
        } else {
            score = 100.0; // Penalize opening new bin if current fit is decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
