        // Only pick this if the mean residual of existing bins is already tight (< 20)
        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count > 0 {
            score += 50.0 + (mean_residual * 0.5);
        } else {
            score -= 100.0;
        }
    }

    // 4. Balance the packing: Avoid creating bins with residuals significantly 
    // different from the current mean.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    // 5. Progression adjustment: As the stream nears the end, become more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
