            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Dynamic threshold for opening new bins:
    // As we approach the end of the stream, prioritize closing bins to reduce total count.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalty decreases as we progress, but remains high to prevent fragmentation.
        score += 35.0 - (progress * 10.0);

        // If we have many open bins that can fit the item, opening a new one is inefficient.
        score += (fitting_bins_count as f64) * 15.0;
    } else {
        // Favor bins that align with the global mean residual to keep future capacity uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Encourage filling bins that are already "half-full" to reduce the number of open bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating 'slivers': space too small to fit typical future items (e.g., < 15).
    // This penalty scales with progress to be more conservative as the stream nears completion.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: if the next item is large, avoid leaving a residual that is slightly
    // too small to accommodate it.
    if next_item_size > 0 {
        let gap = post as i32 - next_item_size as i32;
        if gap < 0 && gap > -10 {
            // Penalize placements that make the bin unable to fit the next item by a small margin.
            score += 40.0 * (1.0 - progress);
        }
    }

    // If this is the last chance for the current item (fitting_bins_count == 1), 
    // significantly reduce the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Global pressure: If we have many open bins, penalize opening a new one 
    // by significantly increasing the score for the new bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0) + (progress * 20.0);
    }

    // Favor bins that align with the mean residual to keep bin fill-levels balanced.
    let dev = (post - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // 2. Harmonic Class Logic: If post_residual is small (e.g., < 10), 
    // it creates "unusable" gaps. We penalize these unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 15.0; // Reward perfect fits
    }

    // 3. Lookahead Logic: If next_item_size can fit in the post_residual,
    // lower the score to prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }

    // 4. Thresholding: If this is the last chance for the current item (fitting_bins_count == 1),
    // and the bin is a new bin (bin_residual == bin_capacity), penalize opening a new bin
    // unless the current fit is extremely inefficient.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0; 
        } else {
            score -= 5.0;
        }
    }

    // 5. Global state pressure: If we have many open bins, prioritize closing gaps.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.5;
    }

    // 6. Harmonic refinement: Use modulo to identify "clean" divisions of capacity.
    // Favors bins that maintain residuals which are multiples of 20 (common item factors).
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual if it leaves a "sliver" (gap too small for most items)
    // Slivers between 1 and 9 are extremely hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: Discourage opening a new bin if we have many bins already
    // If this is a new bin (bin_residual == bin_capacity), add a penalty based on current count
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    }

    // 3. Lookahead Logic: If a future item exists, penalize placements that make it impossible to fit
    // next_item_size if it would have fit otherwise.
    if next_item_size > 0 {
        if post_residual < next_item_size && bin_residual >= next_item_size {
            // We are "blocking" the next item by choosing this bin
            score += 40.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that fits the item, make it highly attractive
    // unless it creates a severe sliver.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If the post_residual is 0, this is a perfect fit. Reward it heavily.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin (if fitting_bins_count > 0)
    // We prioritize using existing bins unless the fit is extremely tight (post_residual is small).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 45.0; 
    }

    // 2. Lookahead matching: reward bins where the post_residual can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: good fit for next item
            score -= 25.0;
        } else if post_residual > 0 {
            // Penalty: residual is too small for the next item, creating "dead space"
            score += 15.0;
        }
    }

    // 3. Density balancing: prefer bins that keep the mean_residual stable
    // If the current post_residual is significantly lower than the mean, we are over-packing (good).
    // If it is higher, we are under-packing (bad).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // 4. Scarcity adjustment: if few bins fit, force the fit to avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression scaling: as the stream nears the end, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
