    }

    // New bin logic: Only open a new bin if the current fit is extremely poor
    // or if we have no other options.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 35.0;

        // If there are other bins that could have fit the item, penalize opening a new one
        if fitting_bins_count > 0 {
            score += 40.0 * (fitting_bins_count as f64);
        }
    } else {
        // Reward bins that bring the residual closer to the global mean,
        // promoting uniform bin utilization.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
