    let mut score = post_res;

    // Penalty for leaving a very small gap that is unlikely to be filled by future items.
    // If the post_residual is less than 10 (the minimum item size), it is likely "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // Lookahead: If we have a next item, penalize bins that cannot fit it 
    // if this is the only bin that could potentially fit it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0 * (1.0 - progress);
    }

    // Heuristic for new bin creation:
    // Only open a new bin if the current fit is extremely poor (large residual).
    // As the stream progresses, become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early on, 
        // but lower the barrier as we approach the end of the stream.
        score = 45.0 + (30.0 * (1.0 - progress));
    } else {
        // If the bin is already open, favor bins that are already "fuller" (lower mean_residual)
        // to keep the number of open bins low.
        score += (mean_residual / bin_capacity as f64) * 10.0;

        // If this is the last chance to fit the item in existing bins, 
        // prioritize it slightly over opening a new one.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "fragmented" space (small, unusable residuals)
    // We heavily penalize residuals that are smaller than the smallest likely item (10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // Lookahead logic: if the next item fits perfectly into the remaining space, prioritize it.
    if next_item_size > 0 && next_item_size <= post_residual {
