    }

    // Harmonic packing: Favor bins where the post_residual is a multiple of common item sizes (e.g., 20, 25)
    // This creates "bins of standard remainders" for future items.
    let remainder_mod = post_residual % 20;
    score += remainder_mod as f64 * 0.5;

