    let progress = step_index as f64 / total_items as f64;
    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;

    // If this is the only bin that can fit the item, prioritize it to avoid opening a new one prematurely
    if fitting_bins_count == 1 && bin_residual >= item_size {
