    }

    // New bin logic: discourage opening a new bin unless the current fill is very poor
    if bin_residual == bin_capacity {
        // If we have many open bins, opening a new one is very expensive
        score += (open_bins_count as f64) * 15.0;
        // If we are late in the stream, opening a new bin is penalized
        score += progress * 50.0;
    }

