    let expansion_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64) * 2.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Combine terms:
    // Base is post_residual. We subtract from the score to prefer smaller residuals.
    // We add penalties to avoid fragmentation and bad lookahead matches.
    let mut score = post + fragmentation_penalty + lookahead_penalty + new_bin_bias + expansion_penalty;

    // If this bin is the only one that fits, give it a significant priority boost
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

