    // We want post_residual to be as small as possible, but not zero if it creates fragmentation.
    score += (post_residual as f64) * 0.5;

    // 4. Global state awareness:
    // If we have many open bins, prioritize tightening existing ones (lower score).
    // If we have very few, be more conservative about opening new ones.
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin. 
        // Only open a new bin if we have too many fragmented bins or if fitting_bins_count is zero.
        score += (open_bins_count as f64) * 2.0;
