        } else {
            // If no fit, normalization to allow new bin creation
            score = 50.0;
        }
    }

    // 3. Lookahead logic: If the next item is large, avoid creating a post_residual
    // that is just slightly too small to fit the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Penalty for creating a 'dead' space that can't fit the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Reward creating a bin that can accommodate the next item perfectly
        if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
            score -= 20.0;
        }
    }

    // 4. Global state adjustment: If many bins are open, prioritize filling the ones with 
    // the least space first to consolidate density, or avoid leaving too many fragmented bins.
    if open_bins_count > 5 {
        if (bin_capacity - bin_residual) < mean_residual as u32 {
            score -= 10.0;
        }
    }

    // 5. Final constraint: Prefer bins that leave just enough room for common item ranges 
    // (e.g., leaving 0-10 or 20-30 space is often better than 11-19).
    let rem = post_residual % 20;
    if rem > 10 && rem < 18 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

