    // We use a quadratic penalty for large residuals to favor "Best Fit" behavior.
    let mut score = post * post * 0.01;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // heavily reward this bin to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
