        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }
    }

    // Deviation penalty: Penalize bins that deviate significantly from the mean 
    // residual of currently open bins to maintain uniform packing density.
    let residual_diff = (post as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
