    // 1. Base penalty for creating small, unusable gaps (the "fragmentation trap")
    // Values between 1 and 9 are notoriously hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // highly prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // 3. New Bin Discipline: Penalize opening a new bin unless existing options are terrible.
    // If we are looking at a new bin (bin_residual == bin_capacity), increase cost
    // based on how many bins are currently open and how well the next item fits elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 4. Tight Fit Bias: Favor bins that are already "tight" to keep others empty.
    // We reward bins that result in a low post_residual relative to the mean.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Progression adjustment: As the stream nears completion, become more aggressive 
    // about closing bins rather than keeping many half-empty ones open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize the remaining space (post_residual).
    // We heavily penalize large post_residuals to push toward tight packing.
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead Logic: If the next item fits into the current post_residual,
    // we reward this placement to keep bins compact for future items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Fragmentation Avoidance: If the post_residual is small but > 0, 
    // it creates "dead space" (e.g., < 10, since min item size is 10).
    // This is highly undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // 4. Global State Awareness: If we have many open bins, penalize opening a new one.
    // If fitting_bins_count is 1, it's the only option; don't penalize.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.5);
        }
    }

    // 5. Dynamic Time Horizon: As we reach the end of the stream, 
    // prioritize closing open bins over creating new ones.
    if progress > 0.85 && bin_residual == bin_capacity {
        score += 100.0;
    }

    // 6. Prefer bins that keep the global mean residual lower (more efficient space usage).
    score += mean_residual * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" (small residuals that are hard to fill later)
    // We penalize residuals between 1 and 9 exponentially.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64).powf(2.5);
    }

    // Dynamic Lookahead Coupling:
    // If we have a next item, penalize bins that cannot fit it after the current placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // New Bin Heuristic:
    // Only open a new bin if the current fit is extremely poor (large residual)
    // or if the stream is nearing completion and we want to consolidate.
    if is_new_bin {
        if fitting_bins_count == 0 {
            // Must open a new bin
            score = -1000.0;
        } else {
            // Heavily penalize opening a new bin if a fitting bin exists, 
            // unless the residual of the best fitting bin is very poor.
            score += 50.0 + (mean_residual * 0.5);
        }
    } else {
        // Favor bins that maintain a residual close to the global average 
        // to keep the bin distribution uniform.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.2;
    }

    // Progress-based pressure:
    // As the stream nears the end, prioritize minimizing the number of open bins 
    // by being more aggressive in filling existing bins (decreasing score for full bins).
    score -= (progress * 10.0) * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (dead space)
    // 2. Harmonic penalty: penalize small remainders that cannot fit likely future items
    // If post_residual is < 10, it is likely "wasted" space since min item size is ~10.
    if post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead integration: 
    // If we have a next_item_size, we want to ensure the post_residual can accommodate it.
    // If the next item cannot fit, we add a penalty proportional to the mismatch.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // Reward bins that leave exactly enough space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 4. Harmonic class bias:
    // Prefer packing into bins that bring the residual closer to 0 or 
    // specific harmonic fractions (e.g., 50, 33, 25) to maximize future fit probability.
    let harmonic_penalty = (post_residual % 25) as f64;
    score += harmonic_penalty * 0.4;

    // 5. New Bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // fitting_bins_count is 0 or the current bin_residual is poor for all existing bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can hold the item
            score += 65.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no bins fit, new bin is the only option
            score -= 10.0;
        }
    }

    // 6. Global pressure:
    // As the stream progresses, become more conservative with new bin openings.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Penalize gaps that are too small to fit common items (10-25)
    // If post_residual is small but > 0, it is a "fragmentation trap".
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins heavily as the stream progresses.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items as f64;
        // The penalty for opening a new bin scales with usage and existing count.
        score += 25.0 + (open_bins_count as f64 * 2.0) + (progress * 15.0);
    } else {
        // 4. Fitting Constraint: If this is the only bin that can fit the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Mean Residual Alignment: Avoid bins that are significantly emptier than the average,
    // as we want to pack bins tightly to minimize the total count.
    if !is_new_bin && (bin_residual as f64) > (mean_residual * 1.2) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize remaining space while prioritizing bins that leave room for the next item.
    // If bin_residual == bin_capacity, we are evaluating a new bin.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalty for opening a new bin: base cost is high, but reduced if current open bins are very full.
        score += 45.0 + (mean_residual * 0.5);
    } else {
        // Reward: prioritize bins where the post_residual is close to the next_item_size (Best Fit).
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score += diff * 0.8;

            // Penalty: if the post_residual is too small to fit the next item (if it's large), 
            // but we have other bins that could fit it, avoid "stranding" small space.
            if post_residual < next_item_size && fitting_bins_count > 1 {
                score += 15.0;
            }
        }

        // Penalty for bins that become "fragmented" (unusable for most items).
        // If post_residual is in the 1-9 range, it's very hard to fill.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    }

    // Progression scaling: as we approach the end of the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large remaining space (post_residual)
    // The base score is already post_residual, so we refine it.

    // 2. Lookahead optimization: If next_item_size fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - progress);
    }

    // 3. Avoid fragmentation: If post_residual is small but > 0, it's often a "dead" space.
    // Penalize narrow gaps that are unlikely to fit future items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // 4. Strategic new bin opening: 
    // If this is a new bin (bin_residual == bin_capacity), only pick it if 
    // the current fitting bins are forced to create "bad" residuals.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we are near the end of the stream
        // or the current bin-packing state is highly fragmented.
        score += 55.0 + (mean_residual * 0.5);

        // If we have many fitting bins, don't open a new one.
        if fitting_bins_count > 0 {
            score += 40.0 * (fitting_bins_count as f64);
        }
    } else {
        // If this is an existing bin, reward bins that bring the mean_residual closer to the item_size,
        // promoting "tight" packing.
        let deviation = (post_residual as f64 - (mean_residual - item_size as f64)).abs();
        score -= deviation * 0.2;
    }

    // 5. Near-end-of-stream adjustment:
    // As we approach the end, prioritize filling existing bins over opening new ones.
    if progress > 0.9 {
        if bin_residual == bin_capacity {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit principle)
    // We add a penalty for creating tiny unusable fragments (0 < post < 10)
    let mut score = post * post;
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 15.0;
    }

    // Lookahead coupling: If next_item_size is large, penalize small post_residuals
    // that would "waste" space that could have been used by the next item.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post < next_item {
            score += (next_item - post) * 2.5;
        }
    }

    // Dynamic adaptation: As the stream progresses, prioritize closing bins (lower mean_residual)
    // to keep the bin density high towards the end of the stream.
    if fitting_bins_count > 0 {
        score -= (mean_residual - post) * (1.0 - progress);
    }

    // New bin penalty: If this is a new bin (bin_residual == bin_capacity), 
    // only choose it if the existing bins are extremely poor fits.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 20.0);
        // Only open new if we have no other options or if current bins are very fragmented
        if fitting_bins_count > 0 {
            score += 50.0 / (fitting_bins_count as f64 + 1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a threshold penalty to prevent unnecessary opening.
    // We only open a new bin if the current fit options are extremely poor (post_residual < 10).
    if bin_residual == bin_capacity {
        score = 25.0 + (open_bins_count as f64 * 0.5);
        return score;
    }

    // 2. Harmonic clustering: penalize post_residuals that leave small, unusable fragments (1-9).
    // These fragments are "dead zones" for the 10-80 item range.
    if post_residual < 10 {
        score += 40.0;
    }

    // 3. Lookahead optimization: If the next item can fit in the current post_residual,
    // reward this placement (Best-Fit principle).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 4. Modulo optimization: Favor bins that leave remainders which are multiples of 20.
    // This helps align future items into common harmonic classes.
    let remainder_mod = post_residual % 20;
    score += remainder_mod as f64 * 0.5;

    // 5. Global pressure: As the stream progresses, tighten the requirements for
    // opening new bins by increasing the cost of small residuals.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.7 {
        score += (1.0 - mean_residual / bin_capacity as f64) * 10.0;
    }

    // 6. Final tie-breaker: Prefer bins that are already "fuller" (lower post_residual)
    // to keep the number of active open bins low.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (gaps smaller than the smallest likely item, e.g., 10)
    // Small gaps (1-9) are highly undesirable as they often remain unused.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Lookahead optimization: If next_item_size is large, favor larger post_residuals
    // to ensure the next item fits, preventing premature bin opening.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 5.0;
    }

    // 3. Open bins pressure: Penalize opening a new bin if other bins are available.
    // If this is a new bin (bin_residual == bin_capacity), add a penalty based on 
    // how many other bins could have accepted this item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += (fitting_bins_count as f64) * 25.0;
    }

    // 4. Efficiency normalization: Favor bins that keep the mean_residual low
    // to maintain high density packing.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // 5. Progression scaling: As we near the end of the stream, prioritize 
    // closing bins (lower post_residual) over keeping them open.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual (Best Fit).
    // The base score (post_residual) already incentivizes this.

    // 2. Lookahead Synergy: If the post_residual can perfectly or nearly accommodate the next item,
    // reduce the score significantly to favor that bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        // Reward configurations where the next item fits snugly.
        score -= (100.0 - fit_gap) * 0.5;
    }

    // 3. Penalty for "Splintering": If the post_residual is too small to fit common items (e.g., < 10),
    // it creates wasted space. Penalize this unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Mean Residual Balancing: If the current bin is significantly worse than the average
    // open bin, penalize it to encourage packing into more efficient bins.
    if (post_residual as f64) > mean_residual * 1.2 {
        score += 15.0;
    }

    // 5. New Bin Threshold: If this is an empty bin (bin_residual == bin_capacity),
    // only choose it if the fitting_bins_count is low, indicating no good existing options.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can fit the item.
            score += 60.0 + (fitting_bins_count as f64 * 5.0);
        } else {
            // If no other bins can fit, opening a new bin is mandatory.
            score = 0.0;
        }
    }

    // 6. Progress weighting: As the stream nears the end, be more aggressive with packing
    // to minimize the total count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize leaving small, unusable gaps.
    // If post_residual is very small (< 10), it often wastes space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Scarcity Logic: If only one bin can fit the current item, prioritize it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 4. Global State Balancing: If current bin is emptier than average, 
    // discourage using it to keep bins packed consistently.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 5. New Bin Thresholding: Dynamic penalty for opening new bins based on stream progress.
    // As the stream nears completion, we become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for new bins, scaling down as we run out of items to prevent stranded leftovers.
        score += 60.0 * (1.0 - progress * 0.5);
    }

    // 6. Extreme Fit Bonus: Perfect fit is always the highest priority.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (lower post_residual)
    let mut score = post_residual as f64;

    // Penalize new bin creation heavily, but ease up as we near the end of the stream
    // to allow for better packing density in the final stages.
    if is_new_bin {
        score += 15.0 * (1.0 - progress).powf(0.5) + (open_bins_count as f64 * 0.5);
    } else {
        // Reward placements that leave a residual space close to the mean_residual 
        // of other bins, promoting uniformity and preventing fragmented small spaces.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // Lookahead heuristic: If the next item is large, avoid leaving a residual
        // that is too small to accommodate it.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 10.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
            }
        }
    }

    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating small, unusable gaps (1-9 range is often "dead space")
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic reward: Favor bins where the post_residual is a multiple of common item sizes
    // This creates "bins of interest" for future items
    if post_residual > 0 {
        let harmonic_mod = (post_residual % 25) as f64;
        score += harmonic_mod * 0.5;
    }

    // Lookahead logic: if next_item_size fits in the post_residual, drastically reduce score
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Discourage opening new bins unless the current options are very poor
    if bin_residual == bin_capacity {
        score += 35.0; 
        // If we are forced to open a new bin, make it expensive unless fitting_bins_count is low
        score += (open_bins_count as f64) * 2.0;
    }

    // If this is the only bin that can fit the item, prioritize it to prevent overflow
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Normalize by progress: as we approach the end, be more aggressive about packing tightly
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

