    // If it's a new bin, apply a progress-dependent cost to discourage fragmentation.
    if is_new_bin {
        // New bins are expensive early, and very expensive late if we have open bins.
        score += 40.0 + (progress * 30.0);
        if fitting_bins_count > 0 {
