pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (fragments)
    // Small fragments (1-9) are usually "dead space". We favor residuals that are 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2. Lookahead Synergy: If next_item_size is known, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next item, we penalize the bin
    // because it forces a new bin to open for the next item anyway.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that act as "containers" for the next item
            score -= 15.0;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the fit is truly poor.
    // If bin_residual == bin_capacity, we are evaluating the "New Bin" option.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low (bins are full).
        // If mean_residual is high, we should use existing bins.
        score += 35.0 + (mean_residual * 0.5);
    } else {
        // 4. Fitting Pressure: If this is the ONLY bin that fits the item, make it highly attractive.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 5. Progress Normalization: As we approach the end of the stream, prioritize 
    // closing bins (lower post_residual) over keeping them open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
