            // Reward perfect or near-perfect fits for the next item
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 2.5;
        } else {
            // Penalize placements that leave too little space for the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. Prevent fragmentation:
    // If we have many open bins, penalize creating a new bin unless it's a very good fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0;
    }

    // 4. Mean Residual Balancing:
    // If this bin's post_residual is significantly better than the global average,
    // favor it to keep the average "tight".
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Critical Threshold:
    // If this is the only bin that fits, we are forced to take it.
    // However, if fitting_bins_count is 1, we lower the score to ensure we don't 
    // accidentally open a new bin when a valid one exists.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress weighting:
    // As we approach the end of the stream, prioritize closing gaps.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-residual space (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is almost empty (fragmentation)
    // We penalize high residuals more heavily as the stream progresses.
    score += (post_residual as f64).powf(1.2) * (1.0 + progress);

    // Lookahead logic: If the next item exists, penalize placements that
    // make it impossible to fit the next item into this bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Significant penalty for stranding the next item
            score += 45.0 * (1.0 - progress);
        } else {
            // Reward placements that leave exactly enough for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // Global state awareness: If we have many bins open, we want to prioritize
    // filling existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // This is a new bin candidate
        if open_bins_count > 0 {
            // Penalize opening a new bin if we have existing capacity
            score += 65.0 - (mean_residual * 0.5);
        }
    } else {
        // If this bin is nearing capacity, reward finishing it off to close it
        if post_residual < 10 {
            score -= 15.0;
        }
    }

    // Adjust for scarcity of fitting bins
    // If this is the only bin that can fit the item, prioritize it to keep options open
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space (Best Fit principle).
    // Lower residual is generally better.
    let mut score = post;

    // Penalty for opening a new bin:
    // Only apply if the bin is empty. We penalize new bins more as the stream progresses,
    // encouraging consolidation of existing space.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64) * (1.0 + progress);
    }

    // Lookahead logic: if next_item_size is large, avoid leaving a residual
    // that is just slightly too small to fit the next item (Dead Space avoidance).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalize creating a gap that is too small for the next item
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else if post_residual >= next_item_size {
            // Reward creating a gap that perfectly fits the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // Coupling with global state:
    // If we have many fitting bins, be more selective (Best Fit).
    // If we are running out of open bins or the mean residual is high, prioritize
    // using existing bins to lower the average waste.
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * 10.0 * (1.0 - progress);

    // Dynamic adjustment based on fitting_bins_count:
    // If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space": residues that are too small to fit common items
    // (10-20 range) but too large to be considered 'full'.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Harmonic class awareness: Prefer filling bins to specific thresholds (e.g., 1/2, 1/3, 1/4 of capacity).
    // This reduces the likelihood of leaving stranded space.
    let fill_fraction = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_fraction > 0.8 {
        score -= 10.0;
    }

    // 4. Scarcity avoidance: If only one bin can fit the item, we are forced to use it.
    // If we have many options, penalize opening a new bin (where bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0;
        } else {
            score -= 5.0; // Baseline cost for opening a necessary new bin.
        }
    }

    // 5. Progression damping: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 5 {
        score -= 20.0;
    }

    // 6. Penalty for creating high-variance bin states (deviation from mean).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (e.g., 1..9), it's "unusable" 
    // because the minimum item size is 1. We penalize gaps that are too small to fit anything.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits in the current post_residual, 
    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
