    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. Global Efficiency: If the current post_residual is significantly worse 
    // than the mean residual of other open bins, increase the penalty.
    if post_residual < (mean_residual as u32) {
        score += (mean_residual - post_residual as f64) * 0.5;
    }

