    if fitting_bins_count == 1 && post_residual == 0 {
        score -= 30.0;
    }

    // 6. Progression Scaling: As the stream nears completion, prioritize clearing open bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 15.0 * (open_bins_count as f64);

    score
}

