    }

    // 3. Lookahead Sensitivity: If a next item exists, favor bins that accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward bins that can fit the next item.
        } else {
            // Penalize bins that leave a gap too small for the next item.
            score += 15.0;
        }
    }

    // 4. Harmonic Fragmentation Control:
    // If we have many open bins, penalize opening new ones or creating high-entropy residual states.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many fitting options.
        score += (open_bins_count as f64 * 2.0) + (progress * 20.0);
    }

    // 5. Residual Alignment: Favor bins closer to the mean residual to keep bin states uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Last Chance Logic: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
