    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If next_item_size > post_residual, this bin is less attractive for future operations.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding for new bin creation:
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        // Only open a new bin if we have no other choice, or if the current bin count is low 
        // and we are early in the stream.
        let openness_factor = (open_bins_count as f64).min(10.0) / 10.0;
        score += 40.0 + (progress * 30.0) + (openness_factor * 15.0);
    } else {
        // If it's a tight fit, reward it based on how much it aligns with the mean_residual
        // to keep bins packed evenly.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= (1.0 - progress) * (deviation * 0.5);
    }

    // Encourage filling up bins that are already partially full
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We favor bins that leave little residual space (Best Fit), but penalize 
    // creating "dead zones" (residuals too small to fit common items).

    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but unusable (1-9 range).
    // If we leave a tiny gap that is unlikely to fit future items, we penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // we prioritize this bin heavily (Best Fit + Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the current 
    // fitting options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, scaled by how many bins are already open.
        // We only open if current open bins are all very tight.
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Density Balancing: If we are near the end of the stream, prioritize 
    // closing existing bins (packing them tighter) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.2;
    }

    // 5. Mean Residual Alignment: Avoid creating bins that deviate significantly 
    // from the average residual of existing bins to keep packing uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Last Chance Logic: If this is the only bin that fits, prioritize it 
    // to prevent unnecessary bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
