    let mut score = post_r;

    // Penalty for creating a 'bad' residual (small gaps that are hard to fill)
    // We penalize values that are small but non-zero, creating a "valley" of death
    // between 1 and 15, which are notoriously difficult to fill in 1D packing.
    if post_r > 0.0 && post_r < 15.0 {
        score += (15.0 - post_r).powi(2) * 2.5;
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // heavily reward this bin to favor packing pairs.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
