    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 + progress);
    }

    // Coupling with the global state: if this bin's residual is significantly
    // worse than the mean, penalize it to encourage balancing.
    if post_r > mean_residual {
        score += (post_r - mean_residual) * 0.5;
    }

    // Final scaling: favor bins that have fewer fitting candidates (tight fit)
    // to preserve more versatile empty space elsewhere.
    if fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64).ln() * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
