    // Dynamic thresholding: as the stream progresses, prioritize closing bins (lower mean_residual)
    // by penalizing bins that deviate significantly from the current mean_residual.
    let deviation = (post_res - mean_residual).abs();
    score += 0.5 * deviation * progress;

    // New Bin Logic: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the fitting bins are "bad" (e.g., they leave
    // awkward residuals).
    if bin_residual == bin_capacity {
