    // Final score: minimize this value
    // post is the primary driver (Best Fit principle), modified by non-linear constraints
    post + fragmentation_penalty + lookahead_weight + new_bin_cost + mean_alignment
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit (minimizing post_residual)
    // 2. Penalty for creating "dead space": post_residual values that are too small to fit common items
    // (items < 10 are rare, so residuals < 10 are effectively dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead logic: If the next item is large, avoid leaving a residual that makes it impossible
    // to fit the next item in this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 4. Harmonic balancing: Favor residuals that are multiples of common item sizes (20, 25, 33).
    // This maximizes the probability of fitting future items perfectly.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 5. Thresholding: If this is the only fitting bin, prioritize it strongly unless it's a terrible fit.
    if fitting_bins_count == 1 && post_residual < 15 {
        score -= 40.0;
    }

    // 6. New bin management: discourage opening a new bin unless the existing ones are very poor fits.
    if bin_residual == bin_capacity {
        // High cost to open a new bin, weighted by the number of existing bins.
        score = 120.0 + (open_bins_count as f64 * 2.0);
    }

    // 7. Progression scaling: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1..9), it creates a "fragment" 
    // that is likely unusable for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits in the current post_residual, 
    // prioritize this bin heavily (Best-Fit Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when existing capacity is sufficient.
    // If this is a new bin (bin_residual == bin_capacity), increase cost based on 
    // how many other bins could have taken the item.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 15.0;

        // Penalize opening a new bin if we are early in the stream
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 20.0;
    }

    // 4. Mean Residual Balancing: Prefer bins that keep the mean residual closer to 
    // the item size to avoid creating extreme variance in bin utilization.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 5. Final Thresholding: Strongly discourage leaving empty space > 50% capacity 
    // unless absolutely necessary.
    if post_residual > (bin_capacity / 2) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the post_residual, but we penalize bins that leave behind
    // space that is too small for the next item, while rewarding fits that align
    // perfectly with the next item.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

