        // Penalty for leaving "dead space" that is smaller than the smallest likely items (10)
        // or specifically smaller than the next item.
        if post_residual < 10 {
            score += 20.0;
        }

        // Avoid fragmentation: penalize if post_residual deviates significantly from the mean
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.5;

        // If this is the last chance to fit the item in existing bins, prioritize it
        if fitting_bins_count == 1 {
