        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score. Lower score = better fit.
    // The goal is to pack tightly while avoiding "orphaned" small residuals (fragmentation)
    // and using lookahead to keep bins open for future items.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual (Best Fit Decreasing logic)
    // We penalize leaving too much space, but prioritize tight fits.
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins heavily, decaying slightly as the stream progresses
    // to allow for more flexibility near the end of the stream.
    if is_new_bin {
        score += 45.0 * (1.0 - (progress * 0.2));
    }

    // 2. Lookahead logic: If a future item exists, penalize placements that leave
    // a residual smaller than the next item (creating unusable gaps).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This is a high-cost state, we are creating "dead" space for the next item.
            score += 35.0;
        } else {
            // Reward placements that leave exactly enough space for the next item.
            if (post_residual as i32 - next_item_size as i32).abs() < 5 {
                score -= 15.0;
            }
        }
    }

    // 3. Global state awareness: If we have many open bins, prioritize filling 
    // the ones with lower residuals (Best Fit) to consolidate space.
    if !is_new_bin {
        // If this bin's residual is already smaller than the global mean, 
        // it's a "tight" bin. Reward filling it further.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // 4. Scarcity handling: If this is the only bin that can fit the item, 
    // it's a "last resort" bin. Use it even if the fit is suboptimal.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 5. Final constraint: Ensure we don't return negative infinity.
    // The score represents the "cost" of this bin choice.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Strategy: 
    // 1. Prioritize Best-Fit (minimize post_residual).
    // 2. Penalize opening a new bin early unless the existing fits are highly suboptimal (large post_residual).
    // 3. Use lookahead next_item_size to discourage creating residuals that cannot fit the next item.

    let mut score = post * 1.5;

    // Penalty for creating a bin with "dead space" that cannot fit the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // If this is a new bin (bin_residual == capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we are struggling to fit items into existing ones
        // or if our current bins are mostly full (high mean_residual indicates empty space)
        let new_bin_penalty = 40.0 + (mean_residual * 0.5) + (progress * 20.0);
        score = new_bin_penalty;
    } else {
        // If fitting_bins_count is low, we are running out of options; reward utilizing existing bins
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Non-linear coupling: punish residuals that are too small to be useful for future items
        // but not small enough to be a perfect fit.
        if post_residual > 0 && post_residual < 20 {
            score += (20.0 - post_residual as f64).powf(1.5);
        }
    }

    // Global pressure: as we approach the end of the stream, prioritize packing density
    score += (1.0 - progress) * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
