    // lower the score to force the use of the existing bin over a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progressive tightening: As we near the end of the stream, prioritize packing density.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress and open bin count.
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 50.0 + (progress * 100.0) + (open_bins_count as f64 * 5.0);
        } else {
            // Must open a new bin
            score = 0.0;
        }
    } else {
        // Reward placements that leave a residual capable of fitting the next item
        // or a common item size (e.g., > 20).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0;
            } else if post_residual > 0 && post_residual < 10 {
                // Penalize "sliver" space that is likely unusable
                score += 20.0;
            }
        }

        // Encourage balancing the load across open bins
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;

        // If this is the last chance for this item (only 1 bin fits), prioritize it
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post;

    // Penalty for opening a new bin:
    // If bin is empty (new bin candidate), apply a dynamic penalty based on progress.
    // Early in the stream, we are more tolerant of new bins to keep future bins flexible.
    // Late in the stream, we penalize new bins heavily to encourage packing into existing space.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    } else {
        // Reward placements that leave a residual close to the average residual of other bins
        // to keep bin states uniform (prevents "orphan" bins with tiny residuals).
        let imbalance = (post - mean_residual).abs();
        score += imbalance * 0.5;

        // Lookahead: If the next item can fit in the current post_residual, 
        // prioritize this bin to avoid fragmentation.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }

        // Pressure adjustment: If we have many open bins, penalize larger post_residuals
        // to force tighter packing when we have plenty of "working" space.
        if open_bins_count > 5 {
            score += post * 0.2;
        }

        // Criticality: If this is the ONLY bin that can fit the item, 
        // aggressively prioritize it to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Non-linear coupling: Exponential penalty for very small residuals (dead space)
    // that are too small for common items (e.g., < 10 units are usually hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post as f64).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We prioritize bins that result in residuals that are multiples of common item sizes (Harmonic alignment).
    // If post_residual is small but not zero, it's often a "fragmentation trap".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
