            // unless the current open bins are very full (low mean_residual).
            score += 40.0 + (mean_residual * 0.5);
        }
    } else {
        // Favor bins that align with the mean density of current open bins.
        // This encourages "Best Fit" behavior implicitly.
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.1;
    }

    // Harmonic class logic: reward residuals that are highly divisible by common item sizes (e.g., 20, 25, 50).
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    // Progress-based scaling: as the stream nears completion, become more aggressive 
    // about filling remaining space to avoid trailing new bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

