        score -= (fitting_bins_count as f64) * 5.0;
    }

    // 4. Progression scaling: As the stream nears the end, prioritize closing bins
    // to minimize the number of open bins that will remain partially filled.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed tightly.
    // Higher post_residual = higher score (worse).
    score += (post_residual as f64) * 1.5;

