    // no other bin can fit the current item effectively.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current item is very large or if we have 
        // very few open bins to choose from.
        score += 45.0 + (item_size as f64 * 0.5);
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Global Density Awareness: If the current bin is significantly emptier 
    // than the global average, discourage adding to it to promote consolidation.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 5. Urgency: As we reach the end of the stream, prioritize fitting items 
    // into existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
