    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean residual alignment: Avoid bins that deviate significantly from the mean 
    // to maintain uniformity across open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Progressive tightening: As we approach the end of the stream, 
    // be more aggressive about filling bins (lowering the penalty for small residuals).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small fragments that cannot fit upcoming items.
    // Base score is the remaining space; we want this to be as small as possible (Best Fit).
    let mut score = post_residual as f64;

    // 1. Lookahead Penalty: If the post_residual is smaller than the next item, 
    // it creates a "fragment" that might be wasted. 
    if next_item_size > 0 && post_residual < next_item_size {
        score += 45.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // 2. Mean Residual Balancing: Avoid leaving bins significantly emptier than the average.
    // If this bin is currently much emptier than the global mean, try to fill it more.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 3. Last Chance/New Bin Logic:
    // If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 4. Empty Bin Penalty: Discourage opening a new bin unless the fit is extremely poor.
    // If we are evaluating a brand-new bin (bin_residual == bin_capacity):
    if bin_residual == bin_capacity {
        // Only open new if we have many bins already or the item is very large relative to capacity.
        score += 30.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Progression scaling: As we approach the end of the stream, be more aggressive
    // to avoid leaving too many half-empty bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Logic: 
    // 1. Prioritize Best Fit (smallest post_residual).
    // 2. Penalize opening a new bin unless the current mean residual is already very low.
    // 3. Use next_item_size to favor bins that can accommodate the subsequent item (lookahead).
    // 4. Incorporate the progress (step_index) to tighten constraints towards the end of the stream.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space (Best Fit component)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin
    if is_new_bin {
        // Only open a new bin if we have many open bins already or if the average space is high
        // This acts as a dynamic threshold for starting new containers
        score += 45.0 + (mean_residual * 0.5) - (progress * 10.0);
    } else {
        // Reward bins that are "tight"
        score -= (bin_capacity - bin_residual) as f64 * 0.1;

        // Lookahead: If this bin can fit the next item, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // If this is the last fitting bin, prioritize it to avoid opening a new one unnecessarily
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Penalize creating "dead space" (small residuals that are hard to fill)
    // Residuals between 1 and 9 are often problematic; penalize them
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Global state adjustment: discourage fragmentation when many bins are open
    score += (open_bins_count as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating a bin that is almost empty, but only if it's not a new bin.
    // If it is a new bin (bin_residual == bin_capacity), we normalize the penalty.
    let is_new_bin = bin_residual == bin_capacity;

    if !is_new_bin {
        // Encourage filling bins tightly. Penalize post_residual exponentially as it grows.
        score += (post_res * post_res) / 10.0;

        // If next_item_size is large and fits in this post_residual, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 1.5;
        }
    } else {
        // Penalty for opening a new bin:
        // We want to open a new bin only when the current open bins have poor residuals.
        // As progress increases, we become more conservative about opening new bins.
        let new_bin_penalty = 25.0 + (progress * 50.0) + (open_bins_count as f64 * 0.5);
        score += new_bin_penalty;
    }

    // Dynamic adjustment based on the state of other bins.
    // If we have many open bins, we should prioritize filling existing ones to keep count low.
    if fitting_bins_count > 0 && !is_new_bin {
        score -= (fitting_bins_count as f64).sqrt() * 5.0;
    }

    // Adjust score based on how the post_residual compares to the global mean residual.
    // If post_residual is much lower than mean_residual, it is an efficient placement.
    if mean_residual > 0.0 {
        score += (post_res - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
