    // If the post_residual is small, it might be perfect, but if it is just slightly 
    // above a threshold that makes it unusable for common item sizes, penalize it.
    // We treat residual values < 10 as "highly desirable" (near-full).
    if post_residual < 10 {
        score -= 50.0;
    }

    // 3. Lookahead Synergy:
    // If next_item_size fits in the post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
