    // 4. New Bin Thresholding:
    // When considering a brand new bin (bin_residual == bin_capacity), 
    // only choose it if the current fitting bins are very poor (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin if an existing one is available
            score += 70.0;
        } else {
            // Neutral if it's the only option
            score += 0.0;
        }
    }

    // 5. Global Density Control:
    // If we have many open bins, penalize creating more by increasing the score.
    // Use mean_residual to gauge if we are fragmenting bins.
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * 0.5;
        if mean_residual < 20.0 {
            score += 10.0;
        }
    }

    // 6. Progression Phase:
    // As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

