    // unless the current open bins have very low average residual (meaning they are already well-packed).
    if bin_residual == bin_capacity {
        score += 40.0 + (mean_residual * 0.3);
    }

    // Global state optimization: penalize opening new bins if we have many already open
    // to encourage consolidating items into existing, non-full bins.
    if bin_residual == bin_capacity && open_bins_count > 5 {
        score += (open_bins_count as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left: lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for leaving small, unusable gaps (1..10) which are hard to fill later.
    // We apply a non-linear penalty that increases as we approach the end of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * (1.0 + 2.0 * progress);
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If the current post_residual is too small for the next item, penalize.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        } else {
            // Reward bins that maintain space for the next item.
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Heuristic for opening a new bin: 
    // Only open a new bin if the current fit is "poor" (leaves a medium gap) 
    // or if the number of open bins is already high (to prevent fragmentation).
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // We only return a low score if the average residual is already high, 
        // meaning existing bins are already poorly utilized.
        score = 25.0 + (mean_residual * 0.5) + (progress * 10.0);
    } else {
        // If it's the last chance to fit an item (fitting_bins_count == 1),
        // we heavily prioritize this bin to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Dampen score by the number of open bins to encourage consolidation in later stages.
    score += (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but non-zero, 
