    }

    // 5. New Bin Constraint: When evaluating a new bin (bin_residual == bin_capacity),
    // apply a high cost to prevent premature bin opening.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If we have many open bins, penalize opening more even further.
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Harmonic Alignment: Favor residuals that align with larger item classes.
    // This helps in keeping "room" for larger items that might arrive later.
    let harmonic_fit = (post_residual % 20) as f64;
    score += harmonic_fit * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
