    } else {
        0.0
    };

    // Favor bins that leave room for the lookahead item (next_item_size).
    // If the lookahead item fits in the post_residual, we reward the fit.
    let lookahead_reward = if next_item_size > 0 && post >= next_item_size as f64 {
        -(post - next_item_size as f64).sqrt() * 2.0
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless the open bins are very full (low mean_residual).
    let new_bin_penalty = if bin_residual == bin_capacity {
