    let last_chance_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -50.0
    } else {
        0.0
    };

    // Combine factors: 
    // post^1.5 encourages filling bins tightly.
    post.powf(1.5) + dead_space_penalty + lookahead_reward + new_bin_penalty + last_chance_bonus
}

