    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progression scaling: As we approach the end, be more aggressive 
    // about filling existing bins to avoid leftover items forcing new bins.
    let progress = step_index as f64 / total_items as f64;
