        (100.0 + (progress * 200.0)) * (1.0 + open_bins_count as f64 * 0.1)
    } else {
        0.0
    };

    // Calculate a "fit quality" metric.
    // We prefer small post_residual (Best Fit), but we penalize bins that 
    // leave "sliver" residuals (e.g., 1-9) which are hard to fill later.
    let sliver_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Lookahead coupling: if the next item is large, we want to prioritize 
    // bins that have enough space to accommodate it.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Reward bins that are closer to the mean residual to maintain packing uniformity
    let deviation_penalty = (post - mean_residual).abs() * 0.5;

    // Final score: minimize this value.
    // post^2 favors smaller residuals (Best Fit behavior)
    // new_bin_penalty ensures we only open new bins when existing ones are poor fits.
    (post * post * 0.05) + sliver_penalty + lookahead_penalty + deviation_penalty + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
