    // Specifically, residuals < 10 are often "dead space" as items are >= 10.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If the next item can fit into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Density Balancing: If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        score += 60.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Threshold: If this is the only bin that fits the current item, 
    // prioritize it to avoid fragmenting the bin count unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Residual Alignment: Favor bins where the post_residual is a multiple of 10 or 25,
    // as these are more likely to be "clean" fractions of the 100 capacity.
    if post_residual % 10 == 0 {
        score -= 5.0;
