        score -= 10.0;
    }

    // 6. Global Pressure: As the stream progresses, prioritize closing bins (lower residual)
    // to consolidate space.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

