    }

    // 3. Mean residual balancing: Penalize bins that deviate significantly from the 
    // current mean residual to maintain uniform bin states.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. Scarcity handling: If this is the only bin that can fit the item, 
    // increase priority to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progress-based scaling: As the stream nears the end, prioritize 
    // filling existing bins more aggressively to avoid trailing leftovers.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
