    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no existing bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Forced to open a new bin
        }
    }

    // 4. Tight Fit Bonus: Favor bins that result in very small residuals (Best Fit).
    // This complements the dead space avoidance by pushing for full bins.
    if post_residual < 5 {
        score -= 15.0;
    }

    // 5. Progression Weighting: As we approach the end of the stream, be more aggressive
    // about closing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals smaller than typical minimum item size)
    // If post_residual is small but > 0, it's often a waste.
    if post_residual > 0 && post_residual < 15 {
