}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_r = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9 range) as they are hard to fill
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        15.0 * (1.0 - (post_r / 10.0))
    } else {
        0.0
    };

    // Reward tighter packing (lower post_residual)
    // Use a non-linear power to prioritize Best-Fit behavior
    let base_score = post_r.powf(1.5);

    // Lookahead logic: if next item exists, penalize bins that cannot fit it
    // after this placement, especially if current bin is the only one left.
    let lookahead_penalty = if next_item_size > 0 {
        if post_residual < next_item_size {
            (next_item_size as f64 - post_r) * 0.5
        } else {
            -(post_r / 100.0) // Small bonus if next item can potentially fit
        }
    } else {
        0.0
    };

    // Dynamic threshold: As the stream progresses, become more aggressive 
    // about keeping bins open (reduce new-bin bias)
    let new_bin_bias = if bin_residual == bin_capacity {
