    } else {
        0.0
    };

    // Favor bins that align with the global mean to keep packing density uniform
    let uniformity_bonus = (post_r - mean_residual).abs() * 0.2;

    base_score + fragmentation_penalty + lookahead_penalty + new_bin_bias + uniformity_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
