            }
        } else {
            // If the next item cannot fit, we penalize the current placement 
            // proportional to how much "wasted" space we are creating.
            score += (bin_capacity - post_residual) as f64 * 0.2;
        }
    }

    // 3. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to do this if existing bins are too tight to fit future items.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are already very full (mean_residual is low)
        // or if we have very few fitting bins.
        if mean_residual > 20.0 && fitting_bins_count > 0 {
            score += 50.0; // Heavily penalize opening a new bin if we have space elsewhere
        } else {
            score -= 5.0; // Slight bias to keep the "frontier" of bins balanced
        }
    }

    // 4. Density Balancing:
    // Prefer placing in bins where the resulting residual is closer to the global mean,
    // reducing variance in bin fill levels.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Progression Weighting:
    // As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
