    if progress > 0.8 && post_residual > 0 {
        score += (post_residual as f64) * 2.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current mean state
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Minimize this (Best Fit).
    let mut score = post;

    // Penalty for opening a new bin:
    // If this is an empty bin (bin_residual == bin_capacity), apply a dynamic penalty
    // that decreases as the stream progresses to allow for more bins late-game.
    if bin_residual == bin_capacity {
        score += 15.0 + (35.0 * (1.0 - progress));
    }

    // Lookahead coupling:
    // If the next item is large, penalize small post_residuals that would orphan the bin.
    if next_item_size > 0 {
        let fit_next = (post >= next_item_size as f64) as i32 as f64;
        // If the current placement leaves a gap too small for the next item, 
        // but the next item is very large, increase penalty.
        score += (1.0 - fit_next) * (next_item_size as f64 * 0.5);
    }

    // Fragmentation avoidance:
    // Penalize post_residuals that are small but unusable (e.g., < 10),
    // unless it is a perfect fit (post == 0).
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - (post / 10.0));
    }

    // Interaction with mean_residual:
    // If this bin's post_residual is significantly better than the global mean,
    // reward it to keep bins tightly packed.
    if post < mean_residual {
        score -= (mean_residual - post) * 0.5;
    }

    // Scarcity factor:
    // If only one bin can fit the item, prioritize it strongly to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (dead space)
    // 2. Harmonic/Modulo penalty: favor residuals that are multiples of common item sizes
    // Modulo 10 represents common item granularity; high post_residual % 10 is often "wasted" space
    let waste_penalty = (post_residual % 10) as f64 * 0.5;
    score += waste_penalty;

    // 3. Lookahead logic: if next_item_size is large, avoid small post_residuals
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot fit the next expected item
            score += 40.0;
        } else {
            // Reward creating a bin that can accommodate the next item
            score -= 15.0;
        }
    }

    // 4. Thresholding: if this is the only fitting bin, heavily discount it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // 5. New bin management: discourage opening new bins unless the fit is extremely poor
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low
        // This forces consolidation into existing bins
        score += 35.0 + (mean_residual * 0.5);
    }

    // 6. Progression scaling: as the stream nears the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
