    // Otherwise, favor filling bins that are already tight (Best Fit logic).
    if bin_residual < bin_capacity {
        // Bias towards filling bins with low residuals to keep mean_residual balanced
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // 5. Progression Scaling: As we approach the end of the stream, 
    // become more desperate to avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
