            score -= 50.0;
        }
    }

    // 4. Relative to mean_residual
    // Reward bins that have a post_residual close to the global mean, 
    // as this keeps bin states clustered and predictable.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

