pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle).
    // Lower residual is generally better (tighter packing).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely.
    if is_new_bin {
        // If there are other bins that could fit this, penalize the new bin heavily.
        if fitting_bins_count > 0 {
            score += 150.0 + (100.0 * (1.0 - progress));
        } else {
            // If no other bin fits, this is a necessary evil.
            score -= 10.0;
        }
    } else {
        // Lookahead: If the next item exists, check if it fits in the current post_residual.
        // If it fits perfectly or leaves little waste, prioritize this bin.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                let waste_after_next = (post_residual - next_item_size) as f64;
                // Reward bins that can accommodate the next item effectively.
                score -= 25.0 * (1.0 / (1.0 + waste_after_next));
            } else {
                // If next item does not fit, penalize if this bin becomes "stale" (too small for most items).
                if post_residual < 10 {
                    score += 20.0;
                }
            }
        }

        // Global State: If the current bin's residual is significantly lower than the mean,
        // it is a "tight" bin. Reward keeping it tight to preserve "loose" bins for later.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // Dynamic Horizon: As we reach the end of the stream, prioritize closing bins
        // (i.e., making post_residual as close to 0 as possible).
        if progress > 0.8 {
            score += (post_residual as f64) * 2.0;
        }
    }

    // Penalize bins that create "unusable" space (e.g., residual < 10, assuming min item size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
