        let deviation = (post_residual as f64 - next_item_size as f64).abs();
        score -= (1.0 - progress) * (100.0 - deviation) / 20.0;
    }

    // Favor bins that have a residual similar to the mean to maintain uniform density.
    let density_penalty = (post_residual as f64 - mean_residual).abs() * 0.1;
