    // If this is an empty bin (bin_residual == bin_capacity), penalize it 
    // based on how many bins are currently open and the fit potential.
    if bin_residual == bin_capacity {
        // Higher penalty if we have many bins already open or if fitting_bins_count is high.
        score += 25.0 + (open_bins_count as f64 * 2.0) + (fitting_bins_count as f64 * 5.0);
    } else {
        // Reward placements that result in a tight fit relative to the mean residual.
        // If post_residual is close to mean_residual, it is a stable placement.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;

        // Aggressive 2-step lookahead: 
        // If the next item fits perfectly into the remaining space, prioritize this bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            let gap_after_next = (post_residual - next_item_size) as f64;
            // Reward bins that leave a very small gap after the next item (near-perfect packing)
            score -= (100.0 - gap_after_next) * 0.5;
        }
    }

    // Progression adjustment: As we approach the end of the stream, prioritize clearing 
    // open bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post-residuals (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for creating "slivers" (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item_size is large, prefer bins that can accommodate it
    if next_item_size > 0 {
        let space_needed_next = next_item_size as f64;
        if (post_residual as f64) < space_needed_next {
            // Penalize bins that will definitely not fit the next item
            score += 20.0 * (1.0 - progress);
        } else {
            // Reward bins that are "perfect" for the next item
            let slack = post_residual as f64 - space_needed_next;
            if slack < 10.0 {
                score -= 15.0;
            }
        }
    }

    // Global state optimization:
    // If we have very few fitting bins, avoid opening a new bin unless necessary
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist
            score += 60.0 * (1.0 - progress * 0.5);
        }
    } else {
        // Encourage balanced filling of existing bins
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Final scaling: favor higher density as we approach the end of the stream
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

