            (next_item_size - post_residual) as f64 * 1.5
        } else {
            0.0
        };
        score += lookahead_penalty * (1.0 - progress);
    }

    // Dynamic thresholding for opening new bins:
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        // Base penalty for new bin is high, but decreases as fitting_bins_count becomes sparse.
        // If no bins can fit the item, fitting_bins_count is 0, we must force a new bin.
        if fitting_bins_count > 0 {
            score += 45.0 + (progress * 30.0);
        } else {
            score = -100.0; // Force selection of new bin
        }
    } else {
        // Reward bins that keep the mean_residual stable
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "unusable" small gaps (1-9) which are often impossible to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Heuristic: Prefer filling bins that are already "half-empty" to keep others empty for potential large items
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (0.5 - fill_ratio).abs() * 20.0;

    // Lookahead logic: If a future item exists, prioritize bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Penalize if current placement forces a new bin for the next item
            score += 15.0;
        }
    }

    // Harmonic constraint: Favor states where post_residual is a multiple of 10 or 25 (common packing divisors)
    if post_residual % 25 == 0 {
        score -= 10.0;
    } else if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // Strategic threshold: If this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Global progression: As the stream nears the end, be more aggressive with packing efficiency
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // New Bin Penalty: If bin_residual == bin_capacity, this is a request to open a new bin.
    // Only do this if the existing options are truly terrible (high scores).
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many open bins, opening another is expensive
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

