    // 1. Dead Space Penalty: If the post_residual is too small to fit common items (10-25),
    // it creates "fragmentation". We penalize residuals in the [1, 9] range heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    // This effectively implements a Best-Fit-Decreasing logic on the fly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bins Pressure: If we are running out of bins or the stream is progressing,
    // we discourage opening new bins (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // Penalize opening a new bin if other bins could have taken the item.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Tight Fit Bonus: Prefer bins that leave very little space (Best Fit),
    // but only if it doesn't fall into the "dead space" trap handled in step 1.
    if post_residual >= 10 && post_residual <= 15 {
        score -= 15.0;
    }

    // 5. Global Efficiency: If the current bin's residual is significantly worse than
    // the mean residual of all open bins, penalize it to force consolidation.
    if (bin_residual as f64) > mean_residual * 1.2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize score.
    // 1. Base cost is the remaining space (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalize opening a new bin heavily unless necessary.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 3. Lookahead: If next_item_size fits perfectly in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward tighter fits for the lookahead item.
        score -= (25.0 / (diff + 1.0));
    }

    // 4. If this is the last chance to fit the item, prioritize it to avoid creating a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Balance residuals: penalize bins that deviate significantly from the mean_residual
    // to keep the fill-levels of open bins somewhat uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Progressive scaling: As we approach the end of the stream, be more conservative with 
    // new bins to prevent straggling small items.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation)
    // Small residuals (< 10) are usually unusable for the given range (10-100)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead integration: 
    // If we have a next item, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward potential for future fit
        }
    }

    // Dynamic thresholding for new bin creation:
    // As we approach the end of the stream, discourage opening new bins.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one works
            score += 60.0 + (progress * 40.0);
        } else {
            // If no bins fit, we must open a new one; normalize score
            score = 0.0;
        }
    } else {
        // Encourage filling bins that are already "half-empty" to keep the mean_residual stable
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;

        // If this bin is the last one that can fit the item, prioritize it to avoid new bin creation
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Global state adjustment: balance distribution across open bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for opening a new bin: proportional to how much space would be wasted 
    // if we don't utilize existing bins, scaled by progress to be more conservative late-game.
    if is_new_bin {
        score += (bin_capacity as f64) * (1.0 + progress);

        // If we have fitting bins, heavily penalize opening a new one unless the fit is perfect.
        if fitting_bins_count > 0 {
            score += 500.0 * (1.0 - progress);
        }
    } else {
        // Non-linear coupling: Reward placements that leave a residual close to the 
        // expected size of the next item (Lookahead synergy).
        if next_item_size > 0 {
            let diff = (post_res - next_item_size as f64).abs();
            score -= (1.0 / (diff + 1.0)) * 20.0;
        }

        // Penalty for creating 'dead space' (residual too small for common items)
        // especially as we progress through the stream.
        if post_res > 0.0 && post_res < 10.0 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Encourage balance across bins by penalizing deviation from the mean_residual
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that cannot fit common item sizes (10-80).
    // If post_residual is small but > 0, it's often better to have 0.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    }

    // 2. Harmonic Lookahead: If next_item_size fits in post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Pressure for New Bin: If we are forced into a bad fit (high post_residual), 
    // allow a new bin if the current bin's residual is significantly above mean.
    if bin_residual == bin_capacity {
        // This is the "New Bin" call.
        // Penalize opening new bins as the stream progresses to consolidate.
        score += 15.0 + (step_index as f64 / total_items as f64) * 20.0;
    } else {
        // Prioritize bins that are already "tight" to keep open_bins_count low.
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // 4. Harmonic Classes: Favor bins where the post_residual is a multiple of 10 or 20,
    // as these are more likely to accommodate subsequent items in a uniform distribution.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // 5. Urgency: If this is the only bin that fits the item, take it regardless of fit quality.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
