    // If post_residual is between 1 and 9, it is highly likely to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by the current number of open bins to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Synergy: If the next item can fit in the current post_residual,
    // reward this placement to keep bins compact.
    if next_item_size > 0 && post_residual >= next_item_size {
