    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item,
    // reward it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Mean residual balance: Penalize bins that deviate significantly from the mean
    // to keep the utilization uniform across open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 6. Progression dampening: As we approach the end of the stream, 
    // prioritize tighter packing (lower residuals) more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed (Standard BF logic)
    // 2. Lookahead Synergy: If the post_residual is close to the next_item_size, we reward it.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward configurations where the next item fits perfectly into the remaining space
        score -= 25.0 * (1.0 / (1.0 + diff));
    }

    // 3. Fragmentation Control: Penalize creating a residual that is too small to be useful
    // (e.g., leaving 1-9 space is often "dead space" since min item size is 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Global Load Balancing: Avoid opening too many bins if the current mean residual is high
    if bin_residual == bin_capacity {
        // This is a new bin candidate. Penalize based on how many bins are already open.
        score += (open_bins_count as f64) * 2.0;
        // If we have plenty of open bins with high residuals, don't open a new one.
        score += mean_residual * 0.5;
    } else {
        // If we are placing in an existing bin, favor bins that are closer to the mean residual
        // to keep usage distribution uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progression Scaling: As we near the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual (already in score)
    // 2. Penalize opening new bins unless the fit is extremely poor
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to or if existing bins are too full to accommodate future items
        if fitting_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0;
        }
    }

    // 3. Lookahead: Prefer bins that can fit the next item if we are nearing capacity
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (synergy)
            score -= 25.0 * (1.0 - progress);
        } else if post_residual > 0 && post_residual < 15 {
            // Penalize creating "sliver" space that is unlikely to fit anything else
            score += 20.0;
        }
    }

    // 4. Global State: If bins are getting crowded, be more aggressive with packing
    if open_bins_count > 0 {
        let density = 1.0 - (mean_residual / bin_capacity as f64);
        if density > 0.7 {
            // Tighten constraints as the system fills up
            score += (1.0 - density) * 10.0;
        }
    }

    // 5. Final adjustment: Prefer bins that are already partially full to keep others empty
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residuals (Best Fit logic)
    let mut score = post;

    // Penalize creating "dead zones" (post_residual < 10) that are hard to fill later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Encourage using existing bins if the lookahead item is large
    // If next_item_size is large, we want to save space in bins with high residuals
    if next_item_size > 50 {
        score -= (bin_residual as f64) * 0.2;
    }

    // Discourage opening a new bin (bin_residual == bin_capacity)
    // unless the current fit is extremely poor
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 20.0);
    }

    // Stability term: balance the residual against the global mean
    // If we are significantly above the mean, we are wasting space
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // If this is the only bin that fits the item, reward selecting it to avoid 
    // unnecessary bin proliferation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Interaction: As the stream progresses, prioritize tighter packing (lower post_residual)
    score += (post * progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits (Best-Fit principle).
    // We penalize larger post_residuals to encourage filling bins as much as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: If post_residual is a multiple of a small integer, 
    // it likely leaves "awkward" space. We penalize residuals that are not multiples 
    // of common item sizes (e.g., 20, 25) to keep residual space "reusable".
    if post_residual > 0 && post_residual % 20 != 0 {
        score += 15.0;
    }

    // 3. Lookahead Calibration: If the next item is large, we want to save space
    // in the current bin if possible, or ensure the next item fits elsewhere.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot accommodate the known next item.
            score += 25.0;
        } else if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
            // Reward "perfect" fits for the lookahead item.
            score -= 20.0;
        }
    }

    // 4. Threshold on New Bin: If this is a new bin (bin_residual == capacity),
    // only open it if the mean residual of existing bins is already very low (fragmented).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 15.0 {
            score += 50.0; // Heavily discourage opening new bins if existing ones have space
        } else {
            score += 40.0; // Baseline penalty for opening a new bin
        }
    }

    // 5. Critical State: If this is the last chance to fit the item in an existing bin,
    // lower the score to force the selection of an existing bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // 6. Progress Scaling: As the stream nears completion, prioritize closing bins
    // by rewarding smaller post_residuals even more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (e.g., < 10), it is likely "unusable" 
    // for future items (min size 10), so we penalize it heavily to force tighter packing.
    if post_residual > 0 && post_residual < 10 {
        score += (100.0 - (post_residual as f64 * 10.0));
    }

    // 2. Lookahead Synergy: If the next item fits in the current post_residual, 
    // reward this bin selection (Best Fit / First Fit combination).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64 * 0.5);
    }

    // 3. Open Bin Pressure: If this is an existing bin (not a new one), 
    // penalize based on open_bins_count to encourage consolidating items 
    // into fewer bins rather than spreading them thin.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64 * 0.2);
    }

    // 4. New Bin Threshold: Discourage opening a new bin unless the current 
    // fitting options are poor (e.g., leaving a very small gap).
    if bin_residual == bin_capacity {
        // High base penalty for opening a new bin, reduced by the urgency of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 + (progress * 15.0);

        // If we are forced to open a new bin, make it less attractive if we have 
        // many empty-ish bins already.
        score += mean_residual * 0.1;
    }

    // 5. Final constraint: Prefer bins that leave no room over bins that leave small gaps.
    // Zero residual is the perfect fit.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // The base score is the post_residual, favoring tighter fits (Best Fit).
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins unless necessary (fitting_bins_count == 0).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 1000.0;
    }

    // 2. Lookahead optimization: If the next item fits perfectly into the post_residual,
    // strongly incentivize this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            // If we have remaining space, penalize leaving a "slivers" (very small gaps).
            // A gap of 1-9 is often worse than a gap of 0.
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // 3. Global balance: If this bin's residual is significantly lower than the mean_residual
    // of all open bins, it is a "tight" bin. We prefer using tight bins for large items
    // to preserve "loose" bins for potential future large items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0 * (item_size as f64 / bin_capacity as f64);
    }

    // 4. Progression scaling: As we approach the end of the stream, prioritize
    // closing bins (minimizing post_residual) over keeping bins open for future items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
