    // reward this bin heavily to avoid leaving a gap that cannot be filled later.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New Bin Penalty: Heavily penalize opening a new bin unless the current 
    // open bins are highly suboptimal (high mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            return 0.0;
        }
        // Increase cost of new bin as we approach the end of the stream
        score += 50.0 + (mean_residual * 2.0) + (progress * 30.0);
    }

    // 4. Scarcity Logic: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Global Efficiency Adjustment: If the mean residual of existing bins is already 
    // low, we are being efficient; penalize placements that drive the residual 
    // significantly away from that average.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 6. Final normalization for near-full bins
    if post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

