    let mut score = post;

    // Penalty for creating a "sliver" (fragmentation) that is too small for common items.
    // We penalize post_residuals that are small but non-zero (e.g., < 10).
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item is large and won't fit in this post_residual,
    // we penalize the current choice to save space for the next item.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 15.0 * (1.0 - progress);
    }

    // Dynamic thresholding: as we progress through the stream, become more aggressive 
    // about filling existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New bin candidate: heavily penalize early in the stream, 
        // but allow it if no other bins fit well.
        score += 45.0 * (1.0 - progress) + (open_bins_count as f64 * 0.5);
    } else {
        // Favor bins that align with the global mean residual to keep distribution uniform.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;

        // If this is the only bin that fits, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Non-linear coupling: penalize high post-residuals quadratically as we approach the end of the stream.
    score += (post / bin_capacity as f64).powf(2.0) * 10.0 * progress;

