    // that leave a gap too small to accommodate the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: penalize opening a new bin if we have many existing bins,
    // but reward perfect fits (post_residual == 0) to consolidate.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Favor bins that are already closer to the mean_residual to keep residuals uniform
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.5;
    }

    // 4. Criticality: If this is the only bin that fits the item (fitting_bins_count == 1),
    // heavily bias toward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // tighten the penalty for creating new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

