pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the waste created in the specific bin.
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (small gaps) that are unlikely to fit future items.
    // If post_residual is small but > 0, it's often worse than having 0 residual.
    if post_residual > 0 && post_residual < 15 {
