    // 3. Dynamic Thresholding: As the stream progresses, become more aggressive in packing
    // to avoid opening new bins late in the game.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
