    // 4. Global State: If this is the only bin that can fit the item, we are forced to pick it.
    // However, if we are considering a new bin (bin_residual == bin_capacity), 
    // penalize opening a new bin if we have many open bins already.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // If we are forced to pick a new bin, try to make it a "good" fit for the current item.
        score += (bin_capacity - item_size) as f64 * 0.1;
    }

    // 5. Balance residuals: Avoid bins that deviate significantly from the mean residual
    // to keep the packing density uniform across all bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 6. Final constraint: If this is the last chance (fitting_bins_count == 1), 
    // heavily favor this bin to avoid creating an unnecessary new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), but we apply
    // non-linear penalties to prevent "fragmentation traps" (very small residuals).
    // Small residuals (1-5) are often "dead space" that cannot fit future items.
    let fragmentation_penalty = if post < 6.0 && post > 0.0 {
        (6.0 - post).powf(2.5) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice
    // to keep the bin open for the next item (or prefer a different bin).
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post).powf(1.5) * 0.8
    } else {
        0.0
    };

    // Global state awareness: 
    // Reward keeping the mean_residual high in early stages to allow flexibility,
    // but tighten constraints (minimize residuals) as we approach the end of the stream.
    let global_efficiency = (post - mean_residual).abs() * (1.0 - progress);

    // New Bin Logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only do this if fitting_bins_count is low or the existing bins are "too full" 
    // to provide good packing for the current and next item.
    let new_bin_base = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 2.5) + (1.0 - progress) * 10.0
    } else {
        0.0
    };

    let mut score = post + fragmentation_penalty + lookahead_penalty + global_efficiency + new_bin_base;

    // Final adjustment: heavily prioritize using existing bins if they fit well, 
    // unless the current fit is extremely poor.
    if fitting_bins_count > 0 && bin_residual != bin_capacity {
        score -= (fitting_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
