    // 4. Dynamic Threshold for New Bin Opening:
    // Only open a new bin if the current options are very poor (large post_residual).
    // As the stream progresses, become more selective about opening new bins.
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            // Penalize opening a new bin if current bins have reasonable capacity
            score += 60.0 + (progress * 40.0);

            // If the mean residual is high, we have enough space elsewhere; don't open new.
            score += mean_residual * 0.5;
        }
    }

    // 5. Critical Constraint: If this is the last chance to fit an item in an existing bin,
    // prioritize it to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead space": bins with residuals too small for likely future items
    // If post_residual is small (e.g., < 10), it's often unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: If a future item is large, favor bins that can accommodate it.
    // If next_item_size is large, avoid leaving a residual that is slightly smaller than next_item_size.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual >= 10 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // New bin logic: Discourage opening a new bin unless the existing fits are very poor.
    if bin_residual == bin_capacity {
        // High base cost for new bin, offset by how crowded existing bins are.
        score = 45.0 + (open_bins_count as f64 * 2.0);

        // If we are near the end of the stream, discourage new bin opening heavily.
        score += 50.0 * progress;
    } else {
        // If this is the last chance to fit an item in an existing bin, reward it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Penalize bins that deviate significantly from the mean residual to keep distribution uniform.
        let deviation = (post_res - mean_residual).abs();
        score += 0.5 * deviation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

