    // This pushes the algorithm towards Best-Fit behavior implicitly
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // Progression scaling: As we reach the end of the stream, prioritize tightest fits
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 2.0;

    // Avoid creating bins that are nearly empty if we have many bins open
    if open_bins_count > 5 && post_residual > (bin_capacity / 2) {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
