    }

    // 3. Global State Balancing: If we are near the end of the stream, prioritize filling existing bins
    // to avoid leaving partially filled bins behind.
    if progress > 0.8 {
        score -= (1.0 - mean_residual / bin_capacity as f64) * 20.0;
    }

    // 4. New Bin Management: 
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it unless necessary.
    if bin_residual == bin_capacity {
