    // If the bin's residual is significantly larger than the global mean,
    // it's likely a "wasteful" bin; penalize it.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // 6. Progress Weighting (End-of-stream optimization)
    // As we approach the end of the stream, prioritize packing density over bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
