    // Base score is the post-residual space (Best Fit principle).
    // Smaller post-residual is usually better, but we want to avoid fragmentation.
    let mut score = post_residual as f64;

    // Penalty for leaving a very small, unusable gap (1..9 is often "dead space").
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item can fit in the current post_residual, 
    // reward this bin to keep the next item compact.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // If this is the ONLY bin that can fit the item, we are forced to take it.
    // We apply a significant incentive to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New bin logic: Penalize opening a new bin heavily unless the current 
    // options are terrible (e.g., leaving a very large gap or forcing high fragmentation).
    if bin_residual == bin_capacity {
        // Only open new if we are forced or if the mean residual is already quite low.
        // Opening a new bin is penalized by the number of currently open bins.
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // Dynamic balancing: If we are late in the stream, prioritize filling existing bins
    // to minimize the final count.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize smaller post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a new bin: non-linearly increases with progress
    // so that opening new bins becomes increasingly expensive as the stream ends.
    if is_new_bin {
        score += 15.0 + (35.0 * progress.powf(1.5));
    }

    // Lookahead logic: if we can fit the next item in the post_residual space, 
    // lower the score to favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - progress);
    }

    // Penalize fragmented bins: if the residual is small (under 10), 
    // it's often wasted space unless it perfectly fits an item.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0 * (1.0 - progress);
    }

    // Coupling with mean_residual: if this bin's post_residual is significantly
    // better (lower) than the current average, reward it.
    let residual_improvement = mean_residual - post_residual as f64;
    score -= residual_improvement * 0.5;

    // If this is the only bin that fits the current item, prioritize it 
    // strongly to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the least space (lower post_residual).
    // The base score is already post_residual, so we apply modifiers to this.

    // 2. Harmonic Class Penalty:
    // Penalize residuals that are "useless" (too small to fit the average remaining item).
    // If post_residual is small but > 0, it often creates "fragmentation".
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // 3. Lookahead coupling:
    // If the next item could potentially fit into the current post_residual, 
    // we reward this placement to keep future options open.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // 4. Density Balancing:
    // If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can fit the item
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 5. Fitting Constraint:
    // If this is the last bin that can fit the current item, prioritize it 
    // to avoid forcing a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progression Scaling:
    // As we approach the end of the stream, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Strict dead space avoidance with lookahead and bin count pressure.
    // Lower score is better.

    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" small gaps (dead space < 10)
    // Small gaps are unlikely to fit future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
