    }

    // 4. Global bin pressure: Penalize opening a new bin if we have too many already open.
    // This pushes the heuristic to consolidate items into fewer bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // Discourage opening a new bin if there is still a lot of space in existing bins
        if mean_residual > 20.0 {
            score += 20.0;
        }
    }

    // 5. Progression awareness: As we approach the end of the stream, 
    // be more aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
