        score = 65.0 + (item_size as f64 * 0.2);
    } else {
        // 4. Mean Residual Balancing: Favor bins that stay near the global mean residual
        // to keep the bin distribution uniform.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.15;
    }

    // 5. Scarcity Penalty: If this is the only bin that can fit the item, 
    // prioritize using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Progressive Tightening: As the stream nears completion, become more aggressive
    // about packing into existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
