    let mut score = post_residual as f64;

    // Penalty for creating "dead zones" (small residuals that are hard to fill)
    // Residuals between 1 and 9 are statistically dangerous for random item distributions
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next item exists, penalize bins that cannot accommodate it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that maintain capacity for the next item
            score -= 5.0;
        }
    }

    // Dynamic Thresholding: If we are near the end of the stream, 
    // prioritize closing bins even at the cost of slight fragmentation.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Global state optimization:
    // If this is the only bin that fits the current item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Manage empty bin opening:
    // If we are considering a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of current bins is high (high fragmentation)
        // or if we have very few bins open relative to the remaining items.
        let fragmentation_penalty = if mean_residual < 20.0 { 40.0 } else { 10.0 };
        score += fragmentation_penalty;

        // As the stream progresses, discourage opening new bins unless necessary
        score += (progress * 50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin heavily at the start, but relax as we approach the end of the stream.
    // This forces tighter packing early on.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress).powf(0.5) * 60.0 + 20.0
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: prioritize smaller post-residual (tighter fit).
    // We apply a non-linear scaling to the post-residual to prioritize "near-perfect" fits.
    let fit_score = post.powf(1.2);

    // Lookahead penalty: if the next item is large, avoid creating small residuals that 
    // will be unusable for the next step.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 0.8
    } else {
        0.0
    };

    // Encourage filling bins that are already "fragmented" (low mean_residual) 
    // to keep the distribution of remaining space uniform.
    let fragmentation_bonus = if !is_new_bin {
        (mean_residual - post) * 0.5
    } else {
        0.0
    };

    // If this is the last bin that can fit the item, reward it to avoid opening a new bin unnecessarily.
    let last_chance_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -25.0
    } else {
        0.0
    };

    fit_score + new_bin_penalty + lookahead_penalty + fragmentation_bonus + last_chance_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "fragmented" space that is hard to fill (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if next_item_size is large, favor larger post_residuals to accommodate it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty if the current placement prevents fitting the next item in this bin
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward if the current placement leaves exact space for next_item_size
            if post_residual == next_item_size {
                score -= 25.0;
            }
        }
    }

    // Harmonic/Modulo logic: favor residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // This helps group items into "full" bins more effectively
    let harmonic_fit = (post_residual % 20) as f64;
    score += harmonic_fit * 0.5;

    // If this is the only bin that fits the item, prioritize it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Balance usage: if we have many bins open, penalize opening a new one
    // bin_residual == bin_capacity represents the "New Bin" candidate
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // As we approach the end of the stream, be more conservative about opening new bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // Favor bins that are closer to the mean residual to maintain uniform bin usage
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
