pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (wasted space)
    // 2. Harmonic/Modulo constraint: favor bins that leave space for common item sizes
    // If post_residual is small, it's either very good (tight fit) or very bad (orphaned space).
    if post_residual < 10 {
        // Extreme tight fit: reward heavily
        score -= 50.0;
    } else if post_residual < 20 {
        // High risk of creating unusable space; penalize slightly
        score += 15.0;
    }

    // 3. Lookahead integration: if next_item_size fits in the post_residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Further reward if it fills the bin almost perfectly
        if (post_residual - next_item_size) < 5 {
            score -= 30.0;
        }
    }

    // 4. Open bin management: discourage opening new bins unless necessary
    if bin_residual == bin_capacity {
        // This is a new bin candidate
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if an existing bin could take the item
            score += 100.0 + (open_bins_count as f64 * 2.0);
        } else {
            // We are forced to open a new bin; normalize the score to be neutral
            score = 50.0;
        }
    }

    // 5. Harmonic pressure: penalize bins that deviate significantly from the mean_residual
    // This encourages filling bins somewhat uniformly to avoid "long tail" bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 6. Progression factor: near the end of the stream, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
