    // If next_item_size is known, favor bins that can accommodate it later.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Strong reward for accommodating lookahead
        } else {
            score += 15.0; // Penalty if current placement blocks the next item
        }
    }

    // 3. Density Balancing:
    // Avoid opening new bins unless necessary (fitting_bins_count == 0).
    // If bin_residual == bin_capacity, it's a new bin candidate.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if existing bins could fit the item
            score += 100.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Necessary to open a new bin
            score = 0.0;
        }
    }

    // 4. Mean Residual Normalization:
    // Prefer bins that stay close to the current global mean to maintain bin uniformity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. Progression Scaling:
    // As the stream nears completion, become more aggressive with packing (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 - (progress * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
