    // If post_residual is < 10, it creates "dead space" that is hard to fill.
    if !is_new_bin && post_residual < 10 {
        score += (10.0 - post_residual as f64).powf(1.5) * 5.0;
    }

    // Lookahead interaction: If next item is large, favor bins that can accommodate it.
    // If post_residual is too small to fit next_item_size, penalize the current choice.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0 * (1.0 - progress);
    }

    // Dynamic thresholding: As we reach the end of the stream, prioritize closing bins
    // over opening new ones by heavily penalizing the new bin candidate.
    if is_new_bin {
        // Base penalty for opening a new bin
        score += 45.0;
        // As the stream progresses, increase the penalty for opening new bins
        score += progress * 30.0;
        // If there are many open bins already, make opening a new one very expensive
        score += open_bins_count as f64 * 2.0;
    } else {
        // Reward bins that bring the residual closer to the global mean (balancing)
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.5;
    }

    // If this is the only bin that can fit the item, prioritize it to avoid wasting a new bin
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

