    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // to keep bins aligned for future "perfect fits".
    let harmonic_alignment = (post_residual % 20) as f64 * 0.5;
    score += harmonic_alignment;

    // 3. Lookahead Sensitivity: If next_item_size fits in this post_residual, 
    // heavily reward this bin to avoid fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Scarcity/Density Heuristic: If this is the last fitting bin, 
    // prevent opening a new bin by aggressively lowering the score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New Bin Threshold: If considering a new bin (bin_residual == bin_capacity),
    // apply a high cost based on the current mean_residual to discourage 
    // opening new bins when existing bins have plenty of space.
    if bin_residual == bin_capacity {
        score = 25.0 + (mean_residual * 0.5);

        // Dynamic scaling: as the stream progresses, it becomes more expensive to open new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 6. Penalty for creating "dead zones" (residuals too small for any likely item, < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
