pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the new bin option (bin_residual == bin_capacity) to prioritize packing into existing space
    // unless the fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    let base_penalty = if is_new_bin { 45.0 + (progress * 20.0) } else { 0.0 };

    // Primary objective: Minimize post_residual, but heavily penalize small "dead" gaps 
    // that are too small for common item sizes (e.g., gaps < 10).
    let dead_space_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post) * 3.5
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.2
    } else {
        0.0
    };

    // Favor bins that align with the current mean_residual to keep bin states uniform.
    let uniformity_bonus = (post - mean_residual).abs() * 0.2;

    // Favor packing when fitting_bins_count is low (last chance) to avoid opening new bins prematurely.
    let urgency_factor = if fitting_bins_count == 1 && !is_new_bin { -10.0 } else { 0.0 };

    let score = post + base_penalty + dead_space_penalty + lookahead_penalty + uniformity_bonus + urgency_factor;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
