    // Penalty for creating "dead zones" (small residuals that likely can't fit future items).
    // If post_residual is < 10, it is likely unusable for any incoming item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // Lookahead logic: if we know the next item, prioritize bins that fit the current item 
    // while leaving space for the next item, or fitting the next item perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item immediately.
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Penalize bins that become "blocked" for the next item.
            score += 15.0;
        }
    }

    // Global state awareness:
    // If we have many open bins, prioritize filling existing ones to reduce count.
    if !is_new_bin {
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // High penalty for opening a new bin if we have many bins that could fit the item.
        score += (fitting_bins_count as f64) * 40.0;
        // As the stream progresses, discourage opening new bins (packing efficiency focus).
        score += progress * 100.0;
    }

    // Statistical balancing:
    // If this bin is significantly below the current mean_residual, it is a "tight" bin.
    // Favor filling tight bins to keep them tight.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

