    let mut score = post;

    // Penalty for creating a 'sliver' (unusable space < 10)
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If next_item_size is large, prioritize keeping space open.
    // If next_item_size is 0, we are at the end, so pack tightly.
    if next_item_size > 0 {
