    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // We scale this penalty by the number of open bins to avoid fragmentation.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0 * progress);
    }

    // Interaction term: penalize deviation from the mean_residual to maintain bin uniformity.
    let residual_dev = (post - mean_residual).abs();
