        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Penalty for opening new bins prematurely:
    // If the bin is new, we apply a significant penalty unless it's the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Strong resistance to opening new bin if space exists
        } else {
            score -= 50.0; // Necessary evil: low cost for mandatory new bin
        }
    }

    // 4. Mean Residual balancing:
    // Try to keep bin residuals close to the global mean to avoid creating 
    // "outlier" bins that are hard to fill later.
    let residual_dev = (post_residual as f64 - mean_residual).abs();
    score += residual_dev * 0.2;

    // 5. Urgency: As we approach the end of the stream, prioritize packing 
    // tightly to close out bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // 6. Avoid "Dead Space" creation:
    // If post_residual is small but > 0, it's often wasted. 
    // Penalize small gaps that are too small for most items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
