    // Lookahead interaction:
    // If the next item is large, penalize small post_residuals that would block it.
    // We use a non-linear coupling: (next_item_size^2) / (post + 1.0)
    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64).powi(2) / (post + 1.0);
        score += lookahead_penalty * 0.15;
    }

    // Density optimization:
    // Favor bins that align with the global mean residual to keep bin states uniform.
    // High deviation from mean_residual increases the score (penalty).
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.25;

    // Scarcity adjustment:
    // If this is the ONLY bin that can fit the item, aggressively favor it
    // to avoid the high cost of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Non-linear curvature:
    // Apply an exponential weight to post_residual to prioritize tighter fits 
    // as the stream progresses, effectively hardening the Best Fit heuristic.
    score += (post / bin_capacity as f64).powf(2.0) * 10.0 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
