pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a 'fragment' that is too small to fit typical future items (e.g., < 10).
    // We penalize post_residuals that are small but non-zero, as they are "dead space".
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5;
    }

    // Lookahead logic: If the next item is large and won't fit in this post_residual,
    // we increase the score (penalize) to encourage finding a bin that accommodates both.
    if next_item_size > 0 && post < (next_item_size as f64) {
        score += (next_item_size as f64 - post) * 1.2;
    }

    // Dynamic thresholding based on stream progress:
    // As we approach the end of the stream, we become increasingly aggressive about packing 
    // tightly (minimizing post_residual) to avoid opening new bins.
    let density_pressure = (open_bins_count as f64 / (1.0 + (progress * 50.0))) * 5.0;
    score += density_pressure;

    // Favor bins that have residuals close to the mean, maintaining high bin utilization consistency.
    let mean_deviation = (post - mean_residual).abs();
    score += mean_deviation * 0.5;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy "opening cost" 
    // that scales with the progress of the stream to force reuse of existing bins.
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 40.0);
    }

    // Reward bins that have just enough space to fit the item exactly (perfect fit).
    if post == 0.0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

