        // This acts as a Best-Fit-Decreasing approximation
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    // 4. Harmonic thresholding: Favor bins that leave a residual which is a multiple of 20
    // (Common item size clusters).
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
