    // 2. Lookahead optimization: If post_residual perfectly matches the next item, heavily reward it
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // 3. Strategic "New Bin" thresholding:
    // If the bin is new, only pick it if the item is large or the mean residual is already very low
    if bin_residual == bin_capacity {
        if item_size > 70 {
            score -= 10.0;
        } else if mean_residual > 30.0 {
            score += 20.0;
        } else {
            score += 60.0; // Strongly penalize opening new bins unless necessary
        }
    }

    // 4. Fitting Pressure: If this is the only bin that can fit the item, prioritize it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 5. Balance residuals: Favor bins that stay close to the global mean residual to keep bins uniform
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 6. Progressive tightening: As we approach the end of the stream, favor tighter fits more aggressively
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
