    let mut score = post;

    // Penalty for leaving "dead space" (small residuals that are hard to fill).
    // We penalize residuals that are smaller than the smallest likely item (10).
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we increase the score (penalty).
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Dynamic Thresholding: As the stream progresses, become more aggressive 
    // about filling bins tightly to avoid trailing waste.
    let tightness_factor = 1.0 + (progress * 2.0);
    score *= tightness_factor;

    // If this is a new bin, apply a significant penalty that scales with progress.
    // Opening a new bin early is cheap, but opening one late is expensive.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is 50.0. 
        // We add a penalty that grows as we reach the end of the stream.
        let new_bin_penalty = 50.0 + (progress * 100.0);
        score = new_bin_penalty;
    } else {
        // Favor bins that have a residual close to the current mean_residual
        // to keep bin packings uniform.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Final constraint: if this is the only bin that fits the item, 
    // strongly incentivize choosing it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
