    // If the mean residual is low, we are constrained; prioritize keeping empty capacity for future items.
    score += (mean_residual - 20.0) * 0.2;

    // 5. Threshold Control: 
    // If this is the only fitting bin (fitting_bins_count == 1), we are forced to use it.
    // We heavily discount this to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 6. New Bin Penalty:
    // If bin_residual == bin_capacity, this is a candidate for a new bin.
    // We only open a new bin if the score of the new bin is significantly better than 
    // the penalty of placing into an existing "bad" bin.
    if bin_residual == bin_capacity {
        score += 35.0;
        // As we approach the end of the stream, opening new bins becomes increasingly expensive.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 7. Large Item Handling:
    // If item is large, favor bins that already have a large residual to avoid stranding small items.
    if item_size > 60 {
        score -= (bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
