    if fitting_bins_count == 1 && post_residual < 20 {
        score -= 50.0;
    }

    // 5. New Bin Threshold:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // Penalize opening a new bin unless the existing bins have very poor average residuals.
    if bin_residual == bin_capacity {
