            score = 0.0;
        }
    } else {
        // 5. Mean residual balancing:
        // Avoid creating bins that deviate significantly from the current average density.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
