    // 3. Density Balancing: Avoid filling bins too early if we have many open bins.
    // Use mean_residual to keep bin filling uniform across the set.
    if (post_residual as f64) < mean_residual {
        score += 5.0;
    }

    // 4. Threshold for New Bin: Only open a new bin if the current fit is extremely poor
