    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Heavily penalize opening a new bin unless the existing fit is extremely poor.
            // A "poor" fit is defined as one leaving a gap that cannot accommodate the mean residual.
            score += 150.0 + (mean_residual * 2.0);
        }
    } else {
        // 4. Harmonic/Modulo pressure:
        // Penalize residuals that are small but not zero (fragmentation).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // 5. If this is the last chance (fitting_bins_count == 1), 
        // reduce the score to ensure we don't open a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // 6. Progress-based scaling: As the stream nears completion, 
    // prioritize closing existing bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space: lower post_residual is generally better (Best Fit).
    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" small gaps.
    // If post_residual is in the range (0, 10), it is very likely to become dead space 
    // since item sizes are >= 10.
    if post_residual > 0 && post_residual < 10 {
