    // If this is a new bin (bin_residual == bin_capacity) and we have other fitting bins,
    // apply a heavy penalty to discourage fragmentation.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Global balance: As we reach the end of the stream, prioritize closing bins
    // by making small residuals more attractive to finish off open space.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 5. Penalize bins that deviate too far from the current mean residual
    // to keep bin fill levels somewhat uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

