    // We heavily penalize large post_residuals.
    score += (post_residual as f64).powi(2) * 0.1;

    // 2. Lookahead Matching: Reward bins where post_residual perfectly accommodates the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
