            score += 5.0;
        }
    }

    // 3. Mean Residual Balancing: Avoid creating bins that deviate significantly from the average state
    // This helps maintain a uniform "tightness" across all open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. Thresholding New Bins: Only open a new bin if the current fit is catastrophic
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the current packing density is already high
        // or if we have very few fitting options.
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 150.0; // Strong penalty to prevent unnecessary new bins
        } else {
            score -= 10.0; // Incentive to start a new bin if no other options exist
        }
    }

    // 5. Progression weighting: As we near the end of the stream, prioritize space utilization
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
