pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: Favor smaller post-residuals (Best Fit logic)
    let mut score = post_res;

    // Penalty for creating "dead space" (residuals too small to fit common items)
    // We penalize residuals in the (0, 10) range heavily as they are likely useless.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * 5.0;
    }

    // Lookahead coupling: If a next item exists, penalize bins that cannot accommodate it
    // if we were to place the current item there.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: As we approach the end of the stream, 
    // be more aggressive about filling existing bins to minimize total count.
    // If fitting_bins_count is 1, this bin is the only option; reward it.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // New Bin Logic: Only open a new bin if the residual of existing bins is 
    // significantly worse than the capacity of a fresh bin, weighted by progress.
    if bin_residual == bin_capacity {
        // High cost to open a new bin early in the stream, lower cost at the end.
        score += 40.0 * (1.0 - progress);
    }

    // Penalize high dispersion of residuals
    score += (post_res - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // We aim to minimize the leftover space.

    // 2. Harmonic/Modulo Penalty:
    // If the post_residual is small but not zero, it creates "dead space" that cannot fit 
    // common small items. We penalize residuals in the (0, 10) range heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic:
    // If we have a next item, check if the current post_residual can accommodate it.
    // If it fits perfectly, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Penalize if we are about to strand a bin that could have fit the next item
            // if we had chosen a different bin.
            score += 5.0;
        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the
    // open bins are very full (mean_residual is low).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average space in existing bins is tight
            score += 40.0 + (mean_residual * 0.5);
        }
