        // If this is the last bin that can fit the item, prioritize it to keep other
        // bins available for potentially larger items.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 6. Progressive scaling:
    // As the stream progresses, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

