    }

    // 4. Harmonic/Modulo pressure: Penalize residuals that create awkward fractions of capacity.
    // We favor residuals that are multiples of 25 (e.g., 0, 25, 50, 75) as they are highly flexible for standard distributions.
    let remainder = post_residual % 25;
    score += (remainder as f64) * 0.5;

    // 5. Threshold for opening new bins: 
    // If the bin is new (bin_residual == bin_capacity), it is only desirable if fitting_bins_count is low 
