    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    // 4. New Bin Logic: If this is a new bin (bin_residual == bin_capacity),
    // only choose it if the penalty for fitting into existing bins is high.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is already very low,
        // suggesting that existing bins are too tight to accommodate future items.
        if open_bins_count > 0 && mean_residual > 20.0 {
