    // If the bin is new (bin_residual == bin_capacity), penalize it 
    // unless the current open bins are already very full (mean_residual is low).
    if bin_residual == bin_capacity {
        score += 40.0 + (mean_residual * 0.5);
    }

    // Progression scaling: as we approach the end of the stream, 
    // be more aggressive about packing into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is in the range [1, 9], 
    // it is highly likely to be wasted because the minimum item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item is large, favor bins that can accommodate it.
    // If post_residual is too small for the next item, penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bin pressure: Penalize opening a new bin if we have existing capacity.
    // If this is a new bin (bin_residual == bin_capacity), increase score significantly
    // unless fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
