        } else {
            // If no other bin fits, this is a necessary new bin.
            score -= 10.0;
        }
    }

    // 4. Tightness bias: Favor bins that are closer to the mean_residual of all bins.
    // This keeps the packing density uniform across all active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, be more aggressive
    // about closing bins (higher penalty for opening new ones).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
