    if bin_residual == bin_capacity {
        // Only open a new bin if the average space in existing bins is very poor.
        // Penalty scales with the number of open bins to avoid bin explosion.
        score += 25.0 + (open_bins_count as f64 * 0.5);
        if mean_residual < 15.0 {
