        }
    } else {
        // 4. Scarcity Logic: If this is the only bin that can fit the item, 
        // give it a strong priority to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // 5. Global State: Penalize bins that deviate too far from the mean_residual
        // to keep usage distribution uniform across bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 6. Temporal Scaling: As we approach the end of the stream, 
    // become more aggressive about fitting items into existing space.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
