pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small slivers (dead space) that are too small for common items (e.g., < 10)
    // The penalty is stronger as the stream progresses, forcing tighter packing late-game.
    let sliver_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * (1.0 + progress * 2.0)
    } else {
        0.0
    };

    // Reward bins that bring the residual closer to the mean_residual of current bins,
    // which encourages balancing bin fullness.
    let balance_factor = (post - mean_residual).abs() * 0.1;

    // Lookahead logic: if next_item_size is large, favor bins with more space (higher post_residual)
    // to accommodate the incoming item, but only if we are not at the very end of the stream.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * (1.0 - progress) * 1.5
    } else {
        0.0
    };

    // Bias against opening new bins early (unless necessary) by scaling with open_bins_count.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    let new_bin_bias = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 0.5) + (progress * 5.0)
    } else {
        0.0
    };

    // Final heuristic: Combine the residual fit (Best Fit) with penalties for fragmentation
    // and lookahead awareness.
    post + sliver_penalty + balance_factor + lookahead_penalty + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
