    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for creating "dead space" (remnants too small to accommodate common incoming items)
    // If post_residual is < 10, it's likely unusable for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // 2. Lookahead correction
    // If we have a next_item_size, prioritize bins that can accommodate BOTH current and next.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for a bin that can "swallow" the next item too (Best-Fit-Lookahead)
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalty if this bin will definitely force a new bin for the next item
            score += 15.0 * (1.0 - progress);
        }
    }

    // 3. Global state balance
    // If the mean_residual is high, we are currently inefficient; favor packing tightly.
    // If mean_residual is low, we are already efficient; allow more flexibility.
    score += (mean_residual - post_residual as f64) * 0.5;

    // 4. New Bin Logic
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // Only open a new bin if the current packing efficiency is extremely low across the board.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -100.0; // Forced to open
        } else {
            // Only open if the average fit is very poor (e.g., all bins are almost full)
            score = 1000.0 - (mean_residual * 10.0);
        }
    } else if fitting_bins_count == 1 {
        // Last chance to fit: if this is the only bin, we MUST take it unless it's a terrible fit.
        if post_residual > 40 {
            score += 200.0; 
        } else {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
