        // Reward bins that have residuals close to the mean, promoting balanced fill-rates
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.5;
    }

    // Nonlinear coupling: Penalize very small gaps that are likely to be wasted (1..9 range)
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Base score is post_residual (Best Fit strategy).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals that are too small for common items).
    // If post_residual is small but > 0, it's likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
