    // 4. Fitting constraints: If this is the last bin that can fit the item, 
    // we should prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 5. Global state normalization:
    // If the mean residual of all open bins is high, we prefer to fill existing bins 
    // (Best Fit) rather than leaving them empty.
    if mean_residual > 30.0 {
        score -= (post_residual as f64) * 0.2;
    }

    // 6. Modulo-based capacity balancing:
    // Encourage filling bins to specific "harmonic" levels (e.g., multiples of 25).
    let target_fit = post_residual % 25;
    if target_fit == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
