    }

    // Pressure factor: if we have many open bins, penalize opening new ones 
    // and favor filling existing ones with higher residuals
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
        if bin_residual == bin_capacity {
            score += 30.0;
        }
    }

    // Bias towards bins that keep the mean residual closer to the item_size,
    // essentially balancing the load across active bins
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that result in smaller residuals (tighter packing).
    // The base score is already post_residual.

    // 2. Lookahead mechanism: If the post_residual is close to the next_item_size, we reward it.
    // This promotes "perfect fit" chains.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
