        // to prevent leaving an item that *must* open a new bin later.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // 5. Global state normalization: If the average bin is getting empty, we want to 
        // fill existing bins more aggressively.
        if mean_residual > 30.0 {
            score += (mean_residual - 30.0) * 0.5;
        }
    }

    // 6. Final progression adjustment: Toward the end of the stream, be more conservative
    // about opening new bins to maximize bin utilization.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
