    }

    // Adjust score based on global state: as we approach the end of the stream,
    // be more aggressive about filling existing bins to minimize the total count.
    score -= (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (lower post_residual is better)
    // We add a penalty for empty bins to prevent premature opening
    let mut score = post;

    // If this is a new bin (bin_residual == capacity), penalize it based on progress.
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 40.0);
    }

    // Lookahead interaction: if the next item is large, avoid leaving tiny residuals 
    // that won't be useful for the next item (e.g., leaving 10 when next is 50).
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        // Reward residuals that are close to the next item size
        score -= (1.0 / (diff + 1.0)) * 5.0;
    }

    // Coupling with mean_residual: avoid creating bins that are significantly 
    // "worse" than the current average state of the packing.
    if post > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    // Penalty for creating a new bin when existing bins could accommodate the item.
    // This scales with the density of the current packing.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
