    // 4. Global balance: Prefer packing into bins that are already "fuller" than the mean
    // to keep the distribution of residuals tight.
    if (bin_capacity - bin_residual) as f64 > mean_residual {
        score -= 5.0;
    }

    // 5. Final constraint: Prefer bins that are the "last chance" to fit the item 
    // to consolidate items before starting new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
