        // We reduce this cost if we are early in the stream or if existing bins are very full.
        let stream_progress = step_index as f64 / total_items as f64;
        score = 65.0 - (stream_progress * 10.0) + (open_bins_count as f64 * 0.5);
    } else if fitting_bins_count == 1 {
