    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bins Pressure: Penalize opening too many bins early in the stream
    let progress = step_index as f64 / total_items as f64;
    let open_bin_penalty = (open_bins_count as f64) * (1.0 - progress) * 5.0;
    score += open_bin_penalty;

    // 3. Lookahead Logic: If the next item can fit in the current post_residual, reward this bin.
    // This is the "Best Fit" refinement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // Penalize if we are blocking the next item from fitting
            score += 15.0;
        }
    }

    // 4. New Bin Constraint: Only open a new bin if the current fit is truly terrible
    // or if we have no other choice.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high to favor consolidation.
        score += 35.0;
        // If we have many open bins that could fit this, heavily penalize opening a new one.
        score += (fitting_bins_count as f64) * 25.0;
    }

    // 5. Mean residual balancing: Prefer bins that stay close to the average state
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

