    }

    // 5. Dynamic time horizon:
    // As we approach the end of the stream, prioritize closing bins (minimizing open_bins_count).
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Mean residual balancing:
    // Favor bins that keep the overall mean residual consistent to avoid fragmentation.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

