    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Favor smaller post_residual (Best Fit principle).
    let mut score = post * post;

    // Interaction: If fitting_bins_count is low, we are constrained; avoid opening new bins.
    if is_new_bin {
