    // 1. Reward tight packing: If the post_residual is exactly the next item size, 
    // it's a perfect match for the 2-step lookahead.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // 2. Penalize "dead space" creation: If post_residual is small but not zero (fragmentation),
    // it is often worse than a slightly larger residual that might fit a future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Strategic New Bin Threshold: If this is a new bin, penalize it heavily unless 
    // the current bin options are all poor (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score += 45.0;

        // If we are at the end of the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 4. Balance current bin utilization against the global mean.
    // If our post_residual is significantly better than the mean, prioritize it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. If this is the only bin that fits the current item, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Lookahead refinement: If next_item_size is large and our post_residual is 
    // smaller than next_item_size, we create a bottleneck. Penalize this.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    score
}

