            // Heavily penalize opening new bins if there are existing options,
            // but scale by progress (be more conservative towards the end).
            score += 60.0 + (progress * 40.0);
        }
    }

    // 4. Fitting Density: If this is the only bin that can fit the item, 
    // prioritize it to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Residual Balancing: If the post_residual is significantly lower than the mean,
