pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We want the smallest post_residual (Best Fit).
    // Penalize new bins heavily early on, but allow them if they create a perfect fit later.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin when existing options exist
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Exponential penalty for opening a new bin when others are available
            score += 150.0 * (1.0 - progress).powf(0.5);
        } else {
            // If no bins fit, we must open one; prioritize it lightly
            score -= 50.0;
        }
    }

    // Lookahead logic: If we have a next item, penalize bins that leave a 
    // "fragment" (a residual too small for the next item).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalty for stranding the next item
            score += 40.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // Encourage density: penalize bins that deviate significantly from the mean_residual
    // This promotes clustering items of similar size into the same bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * residual_deviation * (1.0 + progress);

    // Reward perfect fits (zero residual)
    if post_residual == 0 {
        score -= 20.0;
    }

    // Final scaling for stream progression: encourage tighter packing as the stream ends
    score += (progress * 20.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

