    // We want to minimize remaining space to avoid dead zones.
    let mut score = post_res;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), we apply a progressive
    // penalty that increases as the stream progresses. This forces tighter packing
    // early on and allows more flexibility near the end.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    }

    // Lookahead interaction:
