    // for it, as this forces a new bin later.
    if next_item_size > 0 {
        let next_req = next_item_size as f64;
        if post_res < next_req {
            // High penalty if we create a "dead" space that cannot fit the next item
            score += (next_req - post_res) * 1.5;
        }
    }

    // Coupling with global state:
    // If there are many fitting bins, we prefer the one that leaves the least space (Best Fit).
    // If there is only 1 fitting bin, we are constrained, so we reduce the penalty
    // of that fit to ensure we don't open a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Smooth non-linear penalty for creating "fragmented" bins:
    // If the post_residual is small but not zero (e.g., 1-5), it is often a "bad" fit.
    // We add a parabolic penalty to discourage awkward slivers of space.
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res).powi(2) * 0.5;
    }

    // Interaction with mean_residual:
    // If current bin is significantly better than the average, reward the fit.
    if (post_res as f64) < mean_residual {
        score -= (mean_residual - post_res as f64) * 0.2;
    }

    score
