        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a small, unusable gap (fragmentation)
    // We penalize residuals that are too small to fit common items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // Reward "Best Fit" behavior (minimizing residual)
    // This naturally favors smaller post_residuals
    score += post_residual as f64 * 0.5;

    // Lookahead logic: if a bin fits the next item perfectly (or nearly), prioritize it.
    if next_item_size > 0 {
