    }

    // 5. Global optimization: Favor bins that keep the mean residual balanced.
    // This helps prevent "bin fragmentation" where some bins are nearly full and others are nearly empty.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
