        // Base penalty for opening a new bin.
        score += 45.0;

        // If we have many bins open, penalize opening more.
        score += open_bins_count as f64 * 2.0;

        // If the item is large, the penalty for a new bin is reduced (it's hard to fit).
        score -= (item_size as f64 * 0.4);
    } else {
        // If this bin is the *only* one that fits, give it a significant boost.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Progression adjustment: As we approach the end of the stream, 
    // be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        if bin_residual == bin_capacity {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize "sliver" waste (small remaining space).
    // If post_residual is very small (e.g., < 10), it's often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // 2. Lookahead Coupling: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 55.0 * (1.0 - (next_item_size as f64 / post_residual as f64));
    }

    // 3. Global State Balancing: Avoid fragmenting bins if we are early in the stream.
    // If we have many open bins, penalize opening new ones or using bins that increase the mean_residual.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: only do it if existing bins are poor fits.
        score += 35.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward bins that bring the mean_residual closer to the item_size (keeping bins balanced).
        let imbalance = (post_residual as f64 - mean_residual).abs();
        score += imbalance * 0.5;
    }

    // 4. Scarcity Logic: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Tail-end optimization: As we approach the end of the stream, prioritize packing density over fragmentation.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (lower post_residual).
    let mut score = post_residual as f64;

    // Penalty for creating a new bin: proportional to progress to encourage consolidation
    // early, but allow flexibility as the stream ends.
    if is_new_bin {
        score += 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: if the next item is large, penalize leaving a small post_residual
    // that creates "fragmentation" (useless space).
    if next_item_size > 0 {
        let fragmentation_penalty = if post_residual < next_item_size && post_residual > 0 {
            (next_item_size as f64 - post_residual as f64) * 0.8
        } else {
            0.0
        };
        score += fragmentation_penalty;
    }

    // Efficiency coupling: if there is only one bin that can fit the item, 
    // strongly incentivize using it to avoid opening unnecessary new bins.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global state coupling: avoid cluttering too many bins if the mean residual is high.
    // Penalize new bins if we already have many bins with significant empty space.
    if is_new_bin && open_bins_count > 0 {
        score += mean_residual * 0.2;
    }

    // Non-linear curvature: smooth out the score based on the ratio of current bin state
    // to capacity, penalizing mid-range residuals that are harder to fill.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (fill_ratio - 0.5).powi(2) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
