    // 3. Lookahead synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Open bin pressure: Penalize opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), add a heavy tax.
