    // 5. Fitting bin scarcity: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Global efficiency: Favor bins that keep the mean residual balanced.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
