        if fitting_bins_count > 0 {
            // Strongly penalize opening a new bin if an existing one can fit the item
            score += 60.0 + (open_bins_count as f64 * 0.5);
        } else {
            // Neutral score for opening a bin when no other options exist
            score = 30.0;
        }
    } else {
        // 5. Global optimization: Favor bins that are already "tight"
        // (i.e., keep the mean_residual of bins low)
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 6. Progress adjustment: Toward the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
