        if post_residual >= next_item_size {
            score -= 20.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalty for stranding a large next item by filling this bin too much now.
            score += 15.0 * (next_item_size as f64 / 100.0);
        }
    }

    // 3. Global State: Discourage opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress);
        // Heavily penalize opening a new bin if other bins can fit the item.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 4. Density Balancing: If we have many open bins, penalize low-density placements.
    // We want to pack existing bins tight as the count grows.
    if open_bins_count > 5 {
        score += (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 5. Residual Alignment: Prefer bins that align with the current mean residual.
    // This helps maintain a uniform fill level across the bin set.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Core objective: Minimize residual space (Best Fit), but penalize creating 
    // "orphaned" small residuals that cannot accommodate future items.
    // We use a non-linear penalty for residuals that are smaller than the potential next item.

    let mut score = post * post; 

    // Penalty for creating a bin that is too tight for the next known item (Lookahead influence)
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post).powi(2) * 2.0;
