            score += (bin_capacity - next_item_size) as f64 * 0.5;
        }
    }

    // Smooth coupling: Penalize deviations from the mean residual to encourage uniform bin filling.
    let residual_variance = (post - mean_residual).abs();
    score += residual_variance * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Harmonic/Modulo logic. We treat the bin residual as a state space 
    // where we prioritize "tight" fits (low post_residual) while reserving space
    // for the next_item_size if it fits perfectly into the resulting vacancy.

    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin unnecessarily:
    // If we have fitting bins, penalize the empty bin candidate heavily.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0 + (open_bins_count as f64 * 5.0);
    }

    // 2. Harmonic Lookahead:
    // If the next_item_size fits perfectly into the post_residual, 
    // reward this placement to create a "perfect pair".
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward smaller gaps after the next item is placed.
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Modulo/Fractional alignment:
    // Penalize residuals that are small but unusable (e.g., < 10) 
    // unless they are exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Mean Residual balancing:
    // If this bin's post_residual is significantly worse than the mean of other bins,
    // penalize it to encourage packing tighter bins first.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize closing bins (lower residual).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
