    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are too small to fit common items
    // If post_residual is in (0, 10), it's likely "dead space" because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bins Pressure: Discourage opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless no existing bins can fit the item (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 200.0 + (open_bins_count as f64 * 5.0);
        } else {
            // New bin is necessary, normalize cost to prioritize tighter packing
            score -= 20.0;
        }
    }

    // 3. Lookahead Coupling: If next_item_size is known, favor bins that leave 
    // enough room for the next item (Best Fit variant)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (100.0 - (post_residual as f64 - next_item_size as f64)) * 0.5;
        } else {
            // Penalize bins that leave a gap too small for the next item
            score += 15.0;
        }
    }

    // 4. Global Density Awareness: Penalize bins that deviate significantly from mean_residual
    // This promotes uniform distribution of space across open bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Final adjustment for fitting_bins_count:
    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary bin creation later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space) 
    // but weigh it against the necessity of opening new bins.
    if bin_residual == bin_capacity {
        // If this is a new bin, penalize it heavily unless no other bin fits the item.
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
    }

    // 2. Lookahead Coupling: If the post_residual is close to next_item_size, reward this bin.
    // This implements a primitive Best-Fit-Decreasing style logic.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;

        // If the item perfectly fits the next item, reward it significantly.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. Mean Residual Balancing: Favor bins that stay close to the average state 
    // to prevent fragmentation.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 4. Scarcity Factor: If this is the last fitting bin, prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression Scaling: As we near the end of the stream, be more conservative 
    // with new bin creation.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize creating small unusable gaps.
    // Gaps < 10 are often "dead space" because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead: If next item fits in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Last Chance Heuristic: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 4. Global Density Management: As the stream progresses, favor packing tighter.
    // If the bin is a brand new bin (residual == capacity), penalize it more as we approach the end.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 30.0);
    }

    // 5. Residual Balancing: If the bin is significantly emptier than the global mean, 
    // it's a good candidate to fill up to keep the mean residual consistent.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish large post_residuals (wasted space) 
    // and reward tighter fits.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Significantly increase score if we are forced to open a new bin,
    // but scale it down as we progress through the stream to allow
    // for more aggressive packing towards the end.
    if is_new_bin {
        score += 40.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling:
    // If we have a next item, penalize placements that create a post_residual 
    // too small to accommodate the next item efficiently, unless it's a perfect fit.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // This bin will likely be useless for the next item.
            score += 15.0 * (1.0 - progress);
        } else {
            // Reward bins that leave exactly enough or slightly more than the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 / (1.0 + slack));
        }
    }

    // Fitting density coupling:
    // If this is the only bin that fits, we are forced to use it.
    // If fitting_bins_count is high, we can afford to be pickier.
    if !is_new_bin && fitting_bins_count > 1 {
        // Prefer bins that are already relatively full (closer to mean_residual)
        // to keep "empty" bins available for larger items later.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.2 * deviation;
    }

    // Final non-linear dampening:
    // Ensure that very small post_residuals (near-perfect fills) are prioritized
    // regardless of other factors, using an exponential-like decay.
    if post_residual < 5 {
        score -= 20.0 * (1.0 - (post_residual as f64 / 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual.
    // Penalty for leaving space that is "useless" (too small for most items).
    if post_residual < 10 {
        score -= 20.0; // Reward tight packing
    } else if post_residual < 20 {
        score += 5.0;  // Moderate penalty for "near-miss" tight packing
    }

    // 2. Lookahead logic: if next_item_size fits in current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0; 
    }

    // 3. Avoid opening a new bin if possible, unless the existing bins are already too fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if items can fit elsewhere
            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
            // No other choice
            score = 0.0;
        }
    }

    // 4. Harmonic/Modulo influence: Penalize residuals that are likely to be "orphans"
    // (e.g., residuals in the 10-25 range are often hard to fill).
    if post_residual > 10 && post_residual < 25 {
        score += 30.0;
    }

    // 5. Dynamic adjustment based on stream progression
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late stage: become more aggressive with tight packing, ignore fragmentation
        score -= (1.0 - progress) * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

