    // If post_residual is small but > 0, it's a "sliver" that is hard to fill.
    // We penalize values between 1 and 9 (the smallest possible item size is 1).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization:
    // If we have a next item, check if this bin can fit it.
