    }

    // 3. Open Bin Pressure:
    // Avoid opening new bins unless necessary (fitting_bins_count == 0).
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other options.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Global Packing Efficiency:
    // Favor bins that keep the mean_residual low, but only if we are past the 
    // initial warm-up phase (first 10% of items).
    if step_index > (total_items / 10) {
        if (post_residual as f64) < mean_residual {
