}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but prioritize fits that leave space for the next_item_size.
    // If a bin is empty (new bin candidate), we penalize it based on how many existing bins could have taken the item.

    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin if other bins are available
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0 + (fitting_bins_count as f64 * 5.0);
    }

    // 2. Lookahead matching: If post_residual is close to next_item_size, reward it.
    // We want to minimize the gap between post_residual and next_item_size if next_item_size > 0.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect or near-perfect fit for next item
            let diff = (post_residual - next_item_size) as f64;
            score -= (25.0 - diff).clamp(0.0, 25.0);
        } else {
            // Cannot fit next item, penalize proportionally to how much space is wasted
            score += 15.0;
        }
    }

    // 3. Global efficiency: Favor bins that stay near the current mean_residual to keep density uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 4. Urgency: If this is the last chance to fit an item into an existing bin, favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
