pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large post_residuals (Best Fit logic)
    let mut score = post_res.powf(1.5);

    // Penalty for opening a new bin: if it's the only option or a poor choice, 
    // we make the new bin score significantly higher than the best existing fit.
    if bin_residual == bin_capacity {
        score += 250.0 * (1.0 - (fitting_bins_count as f64 / (open_bins_count as f64 + 1.0)));
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res).powf(1.2);
        }
    }

    // Dynamic pressure: as the stream progresses, favor tighter packing 
    // by increasing the penalty for leaving large residuals.
    score += (post_res * progress * 2.0);

    // Encourage filling bins that are already "below average" to keep the 
    // mean_residual balanced across the system.
    if post_res < mean_residual {
        score -= (mean_residual - post_res).sqrt() * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in smaller residuals (tighter packing)
    // The base score is post_residual.

    // 2. Harmonic/Modulo Penalty:
    // Penalize residuals that are small but not zero, as they create "unusable" gaps
    // (e.g., 1-9 is often considered "dead space" for items 10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead logic (next_item_size):
    // If the next item fits into the current post_residual, reward this bin to keep it open.
    if next_item_size > 0 && next_item_size <= post_residual {
