        } else {
            score -= 10.0; // Encourage opening a new bin if nothing else fits
        }
    }

    // 5. Global state normalization:
    // As the stream progresses, favor packing tighter to avoid late-stage bin proliferation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    // 6. Mean Residual Balance:
    // Penalize bins that deviate too far from the average state of other bins,
    // encouraging uniform wear across bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
