pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1..10) that are unlikely to be filled.
    // We use a non-linear penalty that peaks at post_residual = 5.
    let dead_space_penalty = if post_residual < 10 {
        (10.0 - post) * (10.0 - post) * 2.0
    } else {
        0.0
    };

    // Reward tighter fits (lower post_residual) but balance against the state of the system.
    // If we are late in the stream (progress -> 1.0), we are more desperate to use existing space.
    // If fitting_bins_count is low, we prioritize keeping the bin open.
    let progress_factor = 1.0 + progress;
    let mut score = post * progress_factor + dead_space_penalty;

    // Lookahead logic: if the next item can fit in the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Discourage opening new bins unless necessary. 
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very high (we have lots of empty space)
        // or if we have no other options.
        if fitting_bins_count > 0 {
            score += 50.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0;
        }
    }

    // Normalize by open_bins_count to encourage clustering items in fewer bins.
    score += (open_bins_count as f64) * 0.1;

