            let gap = (post_residual - next_item_size) as f64;
            score -= (50.0 - gap * 1.5).max(10.0);
        } else {
            // Penalize if the current placement makes the next item impossible to fit in this bin.
            score += 15.0;
        }
    }

    // 3. Global Efficiency: If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 4. New Bin Threshold: Discourage opening a new bin unless the current mean_residual is very low.
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 25.0 {
            // If we have open bins with plenty of space, penalize opening a new one.
            score += 60.0;
        } else {
            // Otherwise, keep the score neutral/moderate to allow opening if needed.
            score += 30.0;
        }
    }

    // 5. Progression Scaling: As the stream nears the end, be more aggressive about filling bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: Favor bins that result in small residuals
    // This is the baseline; lower post_residual is generally better.

    // 2. Penalty for creating "stranded" space that cannot fit typical items
    // If the post_residual is less than the minimum observed size (approx 10), 
    // it creates a "dead zone". We add a penalty for residuals < 10.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 3. Lookahead integration: 
    // If next_item_size is known, penalize bins that cannot fit the next item 
    // when they otherwise could have if we chose a different bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Dynamic threshold for opening new bins:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily early on,
    // but reduce the penalty as we approach the end of the stream to favor packing 
    // remaining items tightly.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);

        // If we have many open bins that can fit this item, don't open a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 5. Global state pressure:
    // If we have many open bins, penalize residuals that are significantly 
    // higher than the mean_residual to encourage compaction.
    if open_bins_count > 5 {
        if post_residual as f64 > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.5;
        }
    }

    // 6. Last chance logic:
    // If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // We prioritize bins that leave the least space (Best Fit), 
    // but we apply non-linear penalties to avoid "fragmentation" 
    // where small residuals are left that cannot fit common future items.

    // Base score: Favor smaller post-residual (standard Best Fit)
    let mut score = post * 1.5;

    // Penalize opening a new bin early in the stream, but allow it more freely 
    // as we approach the end (to prevent forcing a bad fit for a final item).
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress).powi(2) + (open_bins_count as f64 * 0.5);
    }

    // Coupling: If fitting_bins_count is 1, this is the "last chance" bin. 
    // If the post_residual is in a "dead zone" (e.g., < 10), it's highly valuable.
    if fitting_bins_count == 1 && post < 10.0 {
        score -= 20.0;
    }

    // Lookahead interaction: If next_item_size is large, penalize bins that 
    // leave a residual smaller than that item size, as it creates stranded space.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next && post > 0.0 {
            // Penalize proportionally to how much space is "wasted" for the next item
            score += (next - post) * 0.8;
        }
    }

    // Adaptive penalty for bins that deviate significantly from the mean_residual
    // This encourages "leveling" the bins to keep them equally available.
    let dev = (residual - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals
    // but reward configurations that leave space for common item sizes.
    score += (post_residual * post_residual) as f64 * 0.05;

    // 2. Harmonic/Modulo logic: Reward residuals that are multiples of 10 or 20,
    // as they are more likely to accommodate future items in a constrained range.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // 3. Lookahead coupling: If next_item_size is large, favor bins that can still fit it.
    // If next_item_size is 0, we are at the end, so prioritize closing bins.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // 4. Thresholding: If this is the only fitting bin, take it to avoid opening a new bin
    // unless the post_residual is extremely wasteful (e.g., > 40).
    if fitting_bins_count == 1 && post_residual < 40 {
        score -= 50.0;
    }

    // 5. New Bin logic: Only open a new bin if the current open bins are very full
    // or if the item is large and fits poorly into existing gaps.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && post_residual > 30 {
            score += 10.0;
        } else {
            score += 60.0; // High penalty to prevent unnecessary new bins
        }
    }

    // 6. Global density balance: If mean_residual is low, we are packing tightly.
    // Penalize bins that deviate significantly from the mean to keep bin usage uniform.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit common items
    // If post_residual is in the range [1, 9], it is highly likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Pressure: If a next item exists, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        }
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have many already open
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If there are other bins that could fit the item, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tightness Reward: Favor filling the bin as much as possible
    // We subtract a fraction of the filled amount to prefer full bins
    let filled_amount = item_size as f64;
    score -= filled_amount * 0.1;

    // 5. Mean residual balancing: Penalize bins that deviate significantly from the mean
    // This helps keep the "open" bins at similar levels of fullness
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a 'sliver' (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward: If post_residual is a perfect match for the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Reward: If post_residual is close to the mean_residual (maintaining uniformity)
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    // Penalty: Discourage opening a new bin if the current bin can fit the item
    // Only apply if this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Higher penalty if many bins are already open to prevent fragmentation
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // Reward: If this is the last chance for the current item
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Progress-based scaling: Be more conservative as the stream nears completion
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating 'slivers' (small, unusable residuals)
    // Residuals < 10 are generally difficult to fill later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Heuristic: Best-Fit Decreasing logic (minimizing post_residual)
    // is naturally captured by the base score. We adjust based on global context.

    // Lookahead mechanism:
    // If the next item is large and the post_residual is too small to accommodate it,
    // we penalize this bin to force the current item into a bin that leaves 
    // enough room for the anticipated next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that create a perfect or near-perfect fit for the next item
            let diff = (post_residual as f64) - (next_item_size as f64);
            if diff < 5.0 {
                score -= 10.0;
            }
        }
    }

    // Dynamic thresholding:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    if fitting_bins_count > 0 && bin_residual != bin_capacity {
        // We are choosing an existing bin. 
        // Apply a slight penalty if the bin residual is significantly higher than the mean
        // to encourage packing items into "fuller" bins first.
        if (bin_residual as f64) > mean_residual {
            score += 5.0 * (1.0 - progress);
        }
    } else if bin_residual == bin_capacity {
        // Penalty for opening a new bin:
        // Increase the cost of new bins as we progress to avoid fragmentation.
        score += 40.0 * (1.0 - (0.2 * progress));

        // If there are other bins that could fit the item, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // We aim to minimize score.
    // 1. Base penalty: The tighter the fit, the better (Best Fit).
    let mut score = post * post;

    // 2. Lookahead coupling: If next_item_size is large, avoid leaving tiny gaps that are unusable.
    // If post_residual is smaller than the next item, that space is effectively wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_residual as f64).powi(2) * 0.5;
        }
    }

    // 3. Dynamic aversion to new bins:
    // As the stream progresses, we become more conservative about opening new bins.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with progress and open_bins_count.
        // We want to force usage of existing bins until late in the stream.
        score += (1.0 - progress) * 500.0 + (open_bins_count as f64 * 10.0);
    } else {
        // 4. Fitting constraints: If this is the last chance to fit, favor it heavily.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }

        // 5. Entropy control: Penalize deviations from the mean_residual to keep bins balanced.
        let deviation = (residual - mean_residual).abs();
        score += deviation * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (fragmentation)
    // We favor bins that result in small post_residuals (Best Fit).
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic:
    // If post_residual is a small divisor of bin_capacity, it is likely to accommodate
    // future items. We reward post_residuals that are multiples of 10 or 20.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual % 20 == 0 {
        score -= 8.0;
    }

    // 3. Lookahead Integration:
    // If the next item fits into the post_residual, drastically reduce the score
    // to keep the bin "active" for the next step.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Further reward if the resulting space after BOTH is very small (near-perfect packing)
        if (post_residual - next_item_size) < 10 {
            score -= 15.0;
        }
    }

    // 4. Threshold Control:
    // If a bin is the only one that can fit the item, we are forced to use it.
    // We lower the score to ensure this bin is preferred over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New Bin Constraint:
    // If the bin is empty (new bin candidate), penalize it unless no other bin fits.
    if bin_residual == bin_capacity {
        score += 35.0; 
        // If we are late in the stream, opening a new bin is more costly.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 6. Global State Coupling:
    // If the current bin is significantly emptier than the mean, penalize using it
    // to encourage filling existing "denser" bins first.
    if (bin_residual as f64) > mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual, but heavily penalize "sliver" gaps (1-9) that are likely to be wasted.
    // Favor fitting into bins that maintain a high mean_residual density.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalty for creating a 'sliver' gap (1..10) which is below the minimum item size (10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Heuristic: If we are forced to open a new bin, penalize it based on how many bins are already open
    // to discourage fragmentation, unless we are nearing the end of the stream.
    if is_new_bin {
        let progress = step_index as f64 / total_items as f64;
        score += (open_bins_count as f64) * 2.0 * (1.0 - progress);
    }

    // Lookahead: If next_item_size is large, prefer bins that can fit it (post_residual >= next_item_size)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // If this is the only bin that can fit the item, prioritize it to avoid unnecessary new bin creation
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Balancing: Favor keeping the mean_residual of open bins high to allow for future flexibility
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin unless absolutely necessary (high fitting_bins_count).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 200.0;
        } else {
            score -= 50.0;
        }
    }

    // 2. Best-Fit logic: prioritize bins that result in smaller residuals.
    // We favor tight fits that leave little room for waste.
    score += (post_residual as f64) * 0.5;

    // 3. Lookahead Matching: If the post_residual is close to the next_item_size,
    // we reward this placement to keep the bin useful for the upcoming item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect match reward: if post_residual matches next_item_size exactly
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                // Proximity reward: how well does the remaining space accommodate the next item?
                score -= (100.0 - (post_residual as i32 - next_item_size as i32).abs() as f64) * 0.2;
            }
        } else {
            // Penalty: if the next item won't fit, penalize based on how much wasted space is created.
            score += 10.0;
        }
    }

    // 4. Global distribution awareness:
    // If the current residual is significantly lower than the mean, we are creating a high-density bin.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 5. Progression awareness:
    // As the stream nears completion, become more aggressive in packing to avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    score
}
